export const CONTENT = JSON.parse("{\"id\":\"theory\",\"docs\":{\"cs-theory/01-logic\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 命题与谓词\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"先把「到底要求什么」说准确，再讨论能不能证明；逻辑也是阅读程序条件和接口契约的共同语言。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"计算机理论 · 第 01 关；基础主线的并行选修\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"无；会读简单整数表达式。\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开高等数理逻辑、完备性定理、SAT 求解器实现。\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"从一道规则谜题开始\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一个构建器只有两条规则：「如果启用了签名，就必须提供证书」「缓存命中或离线包可用时可以继续」。给出一次运行记录，怎样判定它违反了哪条规则？先不要写代码，先区分三个东西：\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"事实的真假、规则的真假、执行某个动作的决定\"}]},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"设 \"},{\"t\":\"code\",\"v\":\"P\"},{\"t\":\"text\",\"v\":\" 表示启用签名，\"},{\"t\":\"code\",\"v\":\"Q\"},{\"t\":\"text\",\"v\":\" 表示提供证书。规则是 \"},{\"t\":\"code\",\"v\":\"P → Q\"},{\"t\":\"text\",\"v\":\"，读作「若 P 则 Q」。它只排除「启用签名但没有证书」；没有启用签名时，这条规则没有要求一定提供或一定不提供证书。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"命题、连接词与等价\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"命题是在给定语境下具有真或假值的陈述。「目录里恰有 4 个文件」固定目录和时刻后是命题；「请打开目录」不是。这里采用经典二值逻辑：一句已经解释好的命题要么真，要么假。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这不是 SQL 的比较。PostgreSQL 18 的文档写明，普通比较在任一输入为 NULL 时得到 null，并称之为 unknown，不是 true 或 false；\"},{\"t\":\"code\",\"v\":\"7 = NULL\"},{\"t\":\"text\",\"v\":\" 的结果是 null，判断空值要写 \"},{\"t\":\"code\",\"v\":\"IS NULL\"},{\"t\":\"text\",\"v\":\"。SQLite 的 NULL 说明也指出，这种结果不能按经典二值从字面推出来，例如 \"},{\"t\":\"code\",\"v\":\"NULL OR true\"},{\"t\":\"text\",\"v\":\" 在常见引擎里为 true，而未知比较不会因为「不是假」就变成真。数据库章讲 SQL。本页不把 NULL 的三值表当成另一种要在这里学完的逻辑。\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"写法\"}],[{\"t\":\"text\",\"v\":\"读法\"}],[{\"t\":\"text\",\"v\":\"为真的条件\"}]],\"rows\":[[[{\"t\":\"code\",\"v\":\"¬P\"}],[{\"t\":\"text\",\"v\":\"非 P\"}],[{\"t\":\"text\",\"v\":\"P 为假\"}]],[[{\"t\":\"code\",\"v\":\"P ∧ Q\"}],[{\"t\":\"text\",\"v\":\"P 且 Q\"}],[{\"t\":\"text\",\"v\":\"两者都真\"}]],[[{\"t\":\"code\",\"v\":\"P ∨ Q\"}],[{\"t\":\"text\",\"v\":\"P 或 Q\"}],[{\"t\":\"text\",\"v\":\"至少一个真，允许都真\"}]],[[{\"t\":\"code\",\"v\":\"P → Q\"}],[{\"t\":\"text\",\"v\":\"P 蕴含 Q\"}],[{\"t\":\"text\",\"v\":\"不是「P 真且 Q 假」\"}]],[[{\"t\":\"code\",\"v\":\"P ↔ Q\"}],[{\"t\":\"text\",\"v\":\"P 当且仅当 Q\"}],[{\"t\":\"text\",\"v\":\"两者真值相同\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"code\",\"v\":\"P → Q\"},{\"t\":\"text\",\"v\":\" 等价于 \"},{\"t\":\"code\",\"v\":\"¬P ∨ Q\"},{\"t\":\"text\",\"v\":\"，也等价于逆否命题 \"},{\"t\":\"code\",\"v\":\"¬Q → ¬P\"},{\"t\":\"text\",\"v\":\"，但通常不等价于逆命题 \"},{\"t\":\"code\",\"v\":\"Q → P\"},{\"t\":\"text\",\"v\":\"。在前面的规则中，「有证书」是「启用签名」的必要条件，不是充分条件。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"日常的「如果…就…」常常暗示原因或预期。这里的蕴含不表示原因。经典逻辑只有真、假两种真值。下面四行是蕴含式在四种赋值下的输出，不是四种真值：按 (P, Q) 的顺序 (真, 真)、(真, 假)、(假, 真)、(假, 假)，\"},{\"t\":\"code\",\"v\":\"P → Q\"},{\"t\":\"text\",\"v\":\" 的结果依次为真、假、真、真。它为假的唯一一行是前件真而后件假；前件为假的两行，结果都为真，只表示这条规则没有被违反。所以「签名关闭，证书未提供」不违反 \"},{\"t\":\"code\",\"v\":\"P → Q\"},{\"t\":\"text\",\"v\":\"。中文「只有 Q，才 P」读成 \"},{\"t\":\"code\",\"v\":\"P → Q\"},{\"t\":\"text\",\"v\":\"，Q 是 P 的必要条件，不是 \"},{\"t\":\"code\",\"v\":\"Q → P\"},{\"t\":\"text\",\"v\":\"。因此「只有通过校验，才允许安装」写成「允许安装蕴含通过校验」；通过校验仍推不出允许安装。通关自测第 1 题是在用这个读法。这四行只核对两个命题变元，不是对更多变元的证明。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"德摩根律是 \"},{\"t\":\"code\",\"v\":\"¬(P ∧ Q) ↔ (¬P ∨ ¬Q)\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"code\",\"v\":\"¬(P ∨ Q) ↔ (¬P ∧ ¬Q)\"},{\"t\":\"text\",\"v\":\"。\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"逻辑等价\"}]},{\"t\":\"text\",\"v\":\"要求对所有真值赋值都相同，不是恰好在某次运行里相同。恒真式对所有赋值为真；可满足式只要求至少一个赋值为真。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"谓词、论域与量词\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"code\",\"v\":\"Ready(x)\"},{\"t\":\"text\",\"v\":\" 的真假依赖对象 x，叫谓词。先分写法、指派和句子。\"},{\"t\":\"code\",\"v\":\"P → Q\"},{\"t\":\"text\",\"v\":\" 与 \"},{\"t\":\"code\",\"v\":\"Ready(x)\"},{\"t\":\"text\",\"v\":\" 首先都是公式，这一层只谈符号怎么组。\"},{\"t\":\"code\",\"v\":\"Ready(x)\"},{\"t\":\"text\",\"v\":\" 的 x 没有被量词绑住，也没有被常元替换，它仍是带自由变元的开公式，不是句子。只规定论域、并规定 Ready 表示「该模块就绪」，这是解释，并不把 x 绑住，开公式因此还不是句子。在这个解释下，若再把 x 指派成某一个模块，才能说这个开公式在该指派下为真或为假；那是指派下的真值，公式本身仍开着。要得到句子，须用量词绑住 x，例如 \"},{\"t\":\"code\",\"v\":\"∀x Ready(x)\"},{\"t\":\"text\",\"v\":\"，或把 x 换成一个不带变元的名字。换论域或改 Ready 的含义，会换成另一个解释。下面先采用「本次构建的全部模块」这个解释，下列各句里的量词已经绑住变元，所以它们是句子：\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"code\",\"v\":\"∀x Ready(x)\"},{\"t\":\"text\",\"v\":\"：每个模块都就绪。\"}]},{\"inlines\":[{\"t\":\"code\",\"v\":\"∃x Ready(x)\"},{\"t\":\"text\",\"v\":\"：至少一个模块就绪。\"}]},{\"inlines\":[{\"t\":\"code\",\"v\":\"∀x ∃y Depends(x,y)\"},{\"t\":\"text\",\"v\":\"：每个模块都有某个依赖，依赖可随模块而不同。\"}]},{\"inlines\":[{\"t\":\"code\",\"v\":\"∃y ∀x Depends(x,y)\"},{\"t\":\"text\",\"v\":\"：存在一个共同依赖，所有模块都依赖它。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"后两句不能交换量词。若模块只有 A、B，且仅 A 依赖 B、B 依赖 A，则第一句成立，却没有一个模块被所有模块依赖。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"否定量词时要翻转量词并否定内部谓词：\"},{\"t\":\"code\",\"v\":\"¬∀x P(x)\"},{\"t\":\"text\",\"v\":\" 等价于 \"},{\"t\":\"code\",\"v\":\"∃x ¬P(x)\"},{\"t\":\"text\",\"v\":\"；\"},{\"t\":\"code\",\"v\":\"¬∃x P(x)\"},{\"t\":\"text\",\"v\":\" 等价于 \"},{\"t\":\"code\",\"v\":\"∀x ¬P(x)\"},{\"t\":\"text\",\"v\":\"。两层量词就把同一规则用两次。\"},{\"t\":\"code\",\"v\":\"¬∀x ∃y Depends(x,y)\"},{\"t\":\"text\",\"v\":\" 先写成 \"},{\"t\":\"code\",\"v\":\"∃x ¬∃y Depends(x,y)\"},{\"t\":\"text\",\"v\":\"，再写成 \"},{\"t\":\"code\",\"v\":\"∃x ∀y ¬Depends(x,y)\"},{\"t\":\"text\",\"v\":\"：有一个模块，它对论域里每个对象都不满足 Depends。这和 \"},{\"t\":\"code\",\"v\":\"∀x ∃y ¬Depends(x,y)\"},{\"t\":\"text\",\"v\":\" 不同，后者允许每个模块各自不依赖一个不同的对象。论域必须写明：镜像集上的全称和平台集上的存在不是同一个变元的两种写法。通关自测第 2 题只是把这两步用到另一句句子上。空论域上，全称为真，存在为假；这不是断言有一个「空对象」。在只有 A、B 的有限论域上逐对检查，只能核对这个论域。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题\",\"id\":\"h-6\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：找出一条违例记录\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"记录是「签名关闭，证书未提供」。这不违反 \"},{\"t\":\"code\",\"v\":\"P → Q\"},{\"t\":\"text\",\"v\":\"，因为 P 为假。记录「签名开启，证书未提供」才是反例。若产品真实需求是「仅在签名开启时才提供证书，并且开启时一定提供」，就应写 \"},{\"t\":\"code\",\"v\":\"P ↔ Q\"},{\"t\":\"text\",\"v\":\"；这比单向规则更强。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"下面用完整 C 程序穷举两变量的真值；表达式都没有副作用。保存为 \"},{\"t\":\"code\",\"v\":\"logic.c\"},{\"t\":\"text\",\"v\":\"，用 \"},{\"t\":\"code\",\"v\":\"gcc -std=c17 -Wall -Wextra -Werror logic.c -o logic\"},{\"t\":\"text\",\"v\":\" 编译。\"}]},{\"t\":\"code\",\"lang\":\"c\",\"code\":\"#include \\u003cassert.h>\\n#include \\u003cstdio.h>\\n\\nint main(void) {\\n    for (int p = 0; p \\u003c= 1; ++p) {\\n        for (int q = 0; q \\u003c= 1; ++q) {\\n            int implication = !p || q;\\n            int contrapositive = q || !p;\\n            assert(implication == contrapositive);\\n            assert(!(p && q) == (!p || !q));\\n            printf(\\\"%d %d %d\\\\n\\\", p, q, implication);\\n        }\\n    }\\n    return 0;\\n}\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"输出的三列为 P、Q、蕴含式：依次是 \"},{\"t\":\"code\",\"v\":\"0 0 1\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"0 1 1\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"1 0 0\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"1 1 1\"},{\"t\":\"text\",\"v\":\"。C 的 \"},{\"t\":\"code\",\"v\":\"&&\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"||\"},{\"t\":\"text\",\"v\":\" 有短路求值，含自增、函数调用等副作用时，不能仅凭真值等价就重排求值；语法见 \"},{\"t\":\"link\",\"v\":\"C 核心概念\",\"href\":\"../../programming-basics/02-core-concepts/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：否定一个带条件的保证\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"「每个已发布包都有校验文件」写为 \"},{\"t\":\"code\",\"v\":\"∀x (Published(x) → HasChecksum(x))\"},{\"t\":\"text\",\"v\":\"。否定它得到 \"},{\"t\":\"code\",\"v\":\"∃x (Published(x) ∧ ¬HasChecksum(x))\"},{\"t\":\"text\",\"v\":\"：找出一个已发布却缺校验文件的包即可，不能只找一个未发布包。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-9\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能为一句约束指定论域、谓词和量词。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能用真值表区分蕴含、逆命题和等价。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能把全称条件的否定改写成明确的反例要求。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-10\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"先写公式或给出反例，再展开答案；这里重视理由，不以猜中真假代替证明。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"把「只有通过校验，才允许安装」写成蕴含式；校验通过是否已保证允许安装？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"否定「存在一个镜像，能构建所有目标平台」，说明每层量词的论域。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"设 P 为真、Q 为假，分别计算 \"},{\"t\":\"code\",\"v\":\"P → Q\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"Q → P\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"P ↔ Q\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"模块集合为空时，「所有模块均已扫描」与「存在已扫描模块」分别是什么真值？这能证明扫描器实际运行过吗？\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"设 A 为允许安装，C 为通过校验，写 \"},{\"t\":\"code\",\"v\":\"A → C\"},{\"t\":\"text\",\"v\":\"。不能推出 \"},{\"t\":\"code\",\"v\":\"C → A\"},{\"t\":\"text\",\"v\":\"，仍可能因为版本不兼容而禁止安装。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"原式为 \"},{\"t\":\"code\",\"v\":\"∃m ∈ 镜像集，∀p ∈ 平台集，Builds(m,p)\"},{\"t\":\"text\",\"v\":\"；否定是 \"},{\"t\":\"code\",\"v\":\"∀m ∈ 镜像集，∃p ∈ 平台集，¬Builds(m,p)\"},{\"t\":\"text\",\"v\":\"。失败的平台可以随镜像改变。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"依次为假、真、假。蕴含式仅在前件真且后件假时为假。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"依次为真、假。空集合没有违例，也没有见证，逻辑结论不能证明运行事件实际发生。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-11\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018-06-06 版。第 50 页给出蕴含的四行真值表：前件为假或后件为真时为真。第 66 页说明未写出的论域，以及否定量词时量词种类对调。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"PostgreSQL 18：Comparison Functions\",\"href\":\"https://www.postgresql.org/docs/current/functions-comparison.html\"},{\"t\":\"text\",\"v\":\" — 任一输入为 NULL 时，普通比较得到 null（unknown），不是 true 或 false。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"SQLite：NULL Handling\",\"href\":\"https://www.sqlite.org/nulls.html\"},{\"t\":\"text\",\"v\":\" — NULL 的真值不能按经典二值从字面推；该页记录了 \"},{\"t\":\"code\",\"v\":\"NULL OR true\"},{\"t\":\"text\",\"v\":\" 等与多引擎对照的结果。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"MIT Mathematics for Computer Science 阅读入口\",\"href\":\"https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-spring-2015/pages/readings/\"},{\"t\":\"text\",\"v\":\" — 开放课教材与练习入口；不同年份章号可能不同。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Review of Proof-Writing\",\"href\":\"https://vertex.degree/appendix/proof-writing.html\"},{\"t\":\"text\",\"v\":\" — Mikhail Lavrov 讲条件、量词与展开定义；本页只借鉴先提问再澄清条件的教学方式，例题为原创。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"返回 计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：集合、关系与函数\",\"href\":\"../02-sets-relations-functions/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"从一道规则谜题开始\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"命题、连接词与等价\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"谓词、论域与量词\"},{\"id\":\"h-6\",\"level\":2,\"text\":\"小例题\"},{\"id\":\"h-7\",\"level\":3,\"text\":\"例一：找出一条违例记录\"},{\"id\":\"h-8\",\"level\":3,\"text\":\"例二：否定一个带条件的保证\"},{\"id\":\"h-9\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-10\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-11\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/02-sets-relations-functions\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 集合、关系与函数\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"集合说明「有哪些」，关系说明「怎样联系」，函数额外要求「每个输入恰有一个输出」。先把这三层分清。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"计算机理论 · 第 02 关；基础主线的并行选修\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"01 命题与谓词。\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开公理集合论、无限基数、SQL 操作和 Java 容器 API。\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"从一道分类谜题开始\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"缓存里有 6 个构建产物，按目标平台分组。两个产物属于同一平台，就把它们放进同一组；「体积不超过」却不能用同样的方法分组。两种联系有什么本质区别？答案不在容器类型，而在\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"关系满足什么性质\"}]},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"集合与笛卡尔积\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"集合不计重复、没有顺序；序列计顺序，且可重复。\"},{\"t\":\"code\",\"v\":\"x ∈ A\"},{\"t\":\"text\",\"v\":\" 表示元素关系，\"},{\"t\":\"code\",\"v\":\"A ⊆ B\"},{\"t\":\"text\",\"v\":\" 表示 A 的每个元素都在 B 中；空集 \"},{\"t\":\"code\",\"v\":\"∅\"},{\"t\":\"text\",\"v\":\" 是每个集合的子集。\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"运算\"}],[{\"t\":\"text\",\"v\":\"含义\"}]],\"rows\":[[[{\"t\":\"code\",\"v\":\"A ∪ B\"}],[{\"t\":\"text\",\"v\":\"属于 A 或 B\"}]],[[{\"t\":\"code\",\"v\":\"A ∩ B\"}],[{\"t\":\"text\",\"v\":\"同时属于 A 和 B\"}]],[[{\"t\":\"code\",\"v\":\"A \\\\ B\"}],[{\"t\":\"text\",\"v\":\"属于 A 但不属于 B\"}]],[[{\"t\":\"code\",\"v\":\"A × B\"}],[{\"t\":\"text\",\"v\":\"所有有序对 \"},{\"t\":\"code\",\"v\":\"(a,b)\"},{\"t\":\"text\",\"v\":\"，其中 a 属于 A、b 属于 B\"}]],[[{\"t\":\"code\",\"v\":\"𝒫(A)\"}],[{\"t\":\"text\",\"v\":\"A 的所有子集组成的集合，叫幂集\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"补集必须相对于一个全集 U，写为 \"},{\"t\":\"code\",\"v\":\"U \\\\ A\"},{\"t\":\"text\",\"v\":\"。当 A、B 有限时，\"},{\"t\":\"code\",\"v\":\"|A × B| = |A||B|\"},{\"t\":\"text\",\"v\":\"；若 \"},{\"t\":\"code\",\"v\":\"|A| = n\"},{\"t\":\"text\",\"v\":\"，每个元素都有选或不选两种可能，所以 \"},{\"t\":\"code\",\"v\":\"|𝒫(A)| = 2ⁿ\"},{\"t\":\"text\",\"v\":\"。\"},{\"t\":\"code\",\"v\":\"∅\"},{\"t\":\"text\",\"v\":\" 与 \"},{\"t\":\"code\",\"v\":\"{∅}\"},{\"t\":\"text\",\"v\":\" 不同，前者没有元素，后者有一个元素。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"二元关系与等价类\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"从 A 到 B 的二元关系是 \"},{\"t\":\"code\",\"v\":\"A × B\"},{\"t\":\"text\",\"v\":\" 的子集；A 上的关系是 \"},{\"t\":\"code\",\"v\":\"A × A\"},{\"t\":\"text\",\"v\":\" 的子集。写 \"},{\"t\":\"code\",\"v\":\"aRb\"},{\"t\":\"text\",\"v\":\" 表示有序对 \"},{\"t\":\"code\",\"v\":\"(a,b)\"},{\"t\":\"text\",\"v\":\" 属于 R。\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"性质\"}],[{\"t\":\"text\",\"v\":\"精确定义\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"自反\"}],[{\"t\":\"text\",\"v\":\"对每个 a，都有 aRa\"}]],[[{\"t\":\"text\",\"v\":\"对称\"}],[{\"t\":\"text\",\"v\":\"aRb 推出 bRa\"}]],[[{\"t\":\"text\",\"v\":\"传递\"}],[{\"t\":\"text\",\"v\":\"aRb 且 bRc 推出 aRc\"}]],[[{\"t\":\"text\",\"v\":\"反对称\"}],[{\"t\":\"text\",\"v\":\"aRb 且 bRa 推出 a = b\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"同时自反、对称、传递的关系叫\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"等价关系\"}]},{\"t\":\"text\",\"v\":\"，它把集合划分为互不相交且覆盖全集的等价类。把 a 的类写成 \"},{\"t\":\"code\",\"v\":\"[a] = {x ∈ A | aRx}\"},{\"t\":\"text\",\"v\":\"。自反保证 \"},{\"t\":\"code\",\"v\":\"a ∈ [a]\"},{\"t\":\"text\",\"v\":\"，所以这些类盖住 A。若 \"},{\"t\":\"code\",\"v\":\"[a]\"},{\"t\":\"text\",\"v\":\" 与 \"},{\"t\":\"code\",\"v\":\"[b]\"},{\"t\":\"text\",\"v\":\" 有公共元素 c，则 aRc 且 bRc。对称得到 cRb，再与 aRc 一起用传递得到 aRb。任取 bRx，由 aRb 与 bRx 得到 aRx，所以 \"},{\"t\":\"code\",\"v\":\"[b] ⊆ [a]\"},{\"t\":\"text\",\"v\":\"；反过来同样得到 \"},{\"t\":\"code\",\"v\":\"[a] ⊆ [b]\"},{\"t\":\"text\",\"v\":\"，两类相等。三条性质都用到了。下面只演示缺传递时的失败：在 \"},{\"t\":\"code\",\"v\":\"{0,1,2}\"},{\"t\":\"text\",\"v\":\" 上令 xRy 表示 \"},{\"t\":\"code\",\"v\":\"|x−y| ≤ 1\"},{\"t\":\"text\",\"v\":\"，它自反、对称，但 0R1 且 1R2，没有 0R2。把「差不超过 1」当成可以分组的等价关系是错的。把这个三元素集合的九对关系列完，只核对了这一个有限例子，不是对一切关系的证明。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"同时自反、反对称、传递的关系叫\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"偏序\"}]},{\"t\":\"text\",\"v\":\"，不要求任意两个元素可比较。例如集合之间的包含关系是偏序；\"},{\"t\":\"code\",\"v\":\"{a}\"},{\"t\":\"text\",\"v\":\" 与 \"},{\"t\":\"code\",\"v\":\"{b}\"},{\"t\":\"text\",\"v\":\" 可能互不包含。反对称不是「不对称」：相等元素仍然可以双向相关。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"函数是有唯一性限制的关系\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"函数 \"},{\"t\":\"code\",\"v\":\"f: A → B\"},{\"t\":\"text\",\"v\":\" 要求 A 中\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"每一个\"}]},{\"t\":\"text\",\"v\":\"元素都有 B 中\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"恰好一个\"}]},{\"t\":\"text\",\"v\":\"输出。A 是定义域，B 是陪域；实际取到的输出组成像集 \"},{\"t\":\"code\",\"v\":\"f(A)\"},{\"t\":\"text\",\"v\":\"，像集不一定等于陪域。\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"单射\"}]},{\"t\":\"text\",\"v\":\"：不同输入不会有相同输出；等价地 \"},{\"t\":\"code\",\"v\":\"f(a)=f(b)\"},{\"t\":\"text\",\"v\":\" 推出 \"},{\"t\":\"code\",\"v\":\"a=b\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"满射\"}]},{\"t\":\"text\",\"v\":\"：陪域里的每个元素都被取到，即 \"},{\"t\":\"code\",\"v\":\"f(A)=B\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"双射\"}]},{\"t\":\"text\",\"v\":\"：既单射又满射，因此有从 B 到 A 的逆函数。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"复合 \"},{\"t\":\"code\",\"v\":\"g∘f\"},{\"t\":\"text\",\"v\":\" 先算 f 再算 g，要求 f 的输出能作为 g 的输入。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"不满射时，陪域里有的元素没有原像，就不存在从整个陪域回到定义域的逆函数。把函数限制到像集上，可能变成双射，那时逆函数的定义域是像集，不是原来的陪域。通关自测第 4 题检查的是一个具体的 \"},{\"t\":\"code\",\"v\":\"f\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本页的关系是有序对组成的集合：同一个对不重复计入，一个对要么属于关系，要么不属于。PostgreSQL 的 \"},{\"t\":\"code\",\"v\":\"SELECT\"},{\"t\":\"text\",\"v\":\" 默认是 \"},{\"t\":\"code\",\"v\":\"SELECT ALL\"},{\"t\":\"text\",\"v\":\"，结果可以保留重复行；去掉重复要另写 \"},{\"t\":\"code\",\"v\":\"DISTINCT\"},{\"t\":\"text\",\"v\":\"。因此查询结果不是这里的集合，除非另外说明没有重复行。比较中的 NULL 也不是「这个有序对为假」：命题章所引的 PostgreSQL 文档写明，\"},{\"t\":\"code\",\"v\":\"=\"},{\"t\":\"text\",\"v\":\" 遇到 NULL 得到 unknown。关系代数教材常常先假设集合和二值成员关系；那个模型覆盖不了 SQL 的重复行和 NULL。数据库章的 SQL 练习不能倒过来当作本页定义已经成立的例子。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题\",\"id\":\"h-7\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：缓存分类为什么可行\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"产物为 \"},{\"t\":\"code\",\"v\":\"{a,b,c,d,e,f}\"},{\"t\":\"text\",\"v\":\"，平台标签依次是 \"},{\"t\":\"code\",\"v\":\"(X,Y,X,Z,Y,Z)\"},{\"t\":\"text\",\"v\":\"。定义 aRb 当且仅当二者平台标签相等。标签相等具有自反、对称、传递性，因此等价类是 \"},{\"t\":\"code\",\"v\":\"{a,c}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"{b,e}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"{d,f}\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"如果改成「体积不超过」，通常不对称，不能当等价关系；若两个不同产物体积相同，双向「不超过」也不推出产物本身相等，因此在产物集合上甚至不一定反对称。只有把对象改成数值体积，通常的 \"},{\"t\":\"code\",\"v\":\"≤\"},{\"t\":\"text\",\"v\":\" 才是那个偏序。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：统计位数的函数\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"让 A 为所有 3 位二进制串，B 为 \"},{\"t\":\"code\",\"v\":\"{0,1,2,3}\"},{\"t\":\"text\",\"v\":\"，f 返回串里 \"},{\"t\":\"code\",\"v\":\"1\"},{\"t\":\"text\",\"v\":\" 的个数。\"},{\"t\":\"code\",\"v\":\"f(001)=f(010)=1\"},{\"t\":\"text\",\"v\":\"，所以不单射；\"},{\"t\":\"code\",\"v\":\"000\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"001\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"011\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"111\"},{\"t\":\"text\",\"v\":\" 分别取到 0、1、2、3，所以满射。若把陪域改成 \"},{\"t\":\"code\",\"v\":\"{0,1,2,3,4}\"},{\"t\":\"text\",\"v\":\"，对应规则仍是函数，却不再满射。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这能帮助理解程序接口：返回值类型类似陪域，实际能返回哪些值类似像集，但具体编程语言的类型系统还含有额外规则。数学关系与关系数据库并非同一层教程；表、主键、SQL 已在 \"},{\"t\":\"link\",\"v\":\"数据库基础\",\"href\":\"../../cs-basics/07-databases/\"},{\"t\":\"text\",\"v\":\" 中讲解，Java 容器操作见 \"},{\"t\":\"link\",\"v\":\"集合框架\",\"href\":\"../../java/02-collections/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-10\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能区分元素、子集、幂集与笛卡尔积。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能逐项检验关系性质，而不凭名字猜测。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能在给定定义域与陪域后判定单射、满射。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-11\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"令 \"},{\"t\":\"code\",\"v\":\"A={a,b}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"B={b,c}\"},{\"t\":\"text\",\"v\":\"，求并集、交集、\"},{\"t\":\"code\",\"v\":\"A \\\\ B\"},{\"t\":\"text\",\"v\":\" 及 \"},{\"t\":\"code\",\"v\":\"|A × B|\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"在 \"},{\"t\":\"code\",\"v\":\"{0,1,2,3,4,5}\"},{\"t\":\"text\",\"v\":\" 上，定义 xRy 当且仅当二者除以 3 的余数相同。列出等价类，并说明传递性。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"正整数上的整除关系是偏序吗？2 与 3 可比较吗？\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"函数 \"},{\"t\":\"code\",\"v\":\"f: {0,1,2} → {0,1,2,3}\"},{\"t\":\"text\",\"v\":\" 规定 \"},{\"t\":\"code\",\"v\":\"f(x)=x+1\"},{\"t\":\"text\",\"v\":\"，它是否单射、满射、有该陪域上的逆函数？\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"并集 \"},{\"t\":\"code\",\"v\":\"{a,b,c}\"},{\"t\":\"text\",\"v\":\"，交集 \"},{\"t\":\"code\",\"v\":\"{b}\"},{\"t\":\"text\",\"v\":\"，差集 \"},{\"t\":\"code\",\"v\":\"{a}\"},{\"t\":\"text\",\"v\":\"；笛卡尔积有 4 个有序对。\"}],\"n\":1},{\"inlines\":[{\"t\":\"code\",\"v\":\"{0,3}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"{1,4}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"{2,5}\"},{\"t\":\"text\",\"v\":\"。若 x、y 余数相同，y、z 余数相同，则 x、z 余数也相同；自反与对称同样来自余数相等。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"是：每个正整数整除自身，互相整除的正整数相等，整除具有传递性。2 与 3 互不整除，所以不可比较；偏序不必是全序。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"单射，因为 \"},{\"t\":\"code\",\"v\":\"x+1=y+1\"},{\"t\":\"text\",\"v\":\" 推出 \"},{\"t\":\"code\",\"v\":\"x=y\"},{\"t\":\"text\",\"v\":\"。不满射，因为取不到 0；因而不存在从整个陪域到定义域的逆函数，但可在像集 \"},{\"t\":\"code\",\"v\":\"{1,2,3}\"},{\"t\":\"text\",\"v\":\" 上取逆。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-12\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018-06-06 版第 4 章：集合不计重复、没有顺序；第 10 章讲等价关系与偏序。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"PostgreSQL 18：SELECT\",\"href\":\"https://www.postgresql.org/docs/current/sql-select.html\"},{\"t\":\"text\",\"v\":\" — \"},{\"t\":\"code\",\"v\":\"SELECT ALL\"},{\"t\":\"text\",\"v\":\" 是默认，保留重复行；\"},{\"t\":\"code\",\"v\":\"DISTINCT\"},{\"t\":\"text\",\"v\":\" 才删除重复行。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Book of Proof\",\"href\":\"https://richardhammack.github.io/BookOfProof/\"},{\"t\":\"text\",\"v\":\" — 免费证明入门教材；集合、关系、函数适合反复查定义。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Walks, Paths, and Cycles\",\"href\":\"https://vertex.degree/beginning/walks.html\"},{\"t\":\"text\",\"v\":\" — 展示图的可达性怎样产生等价关系；本页分类与位串例子独立编写。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：命题与谓词\",\"href\":\"../01-logic/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：证明与归纳\",\"href\":\"../03-proofs-induction/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"从一道分类谜题开始\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"集合与笛卡尔积\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"二元关系与等价类\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"函数是有唯一性限制的关系\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"小例题\"},{\"id\":\"h-8\",\"level\":3,\"text\":\"例一：缓存分类为什么可行\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例二：统计位数的函数\"},{\"id\":\"h-10\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-11\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/03-proofs-induction\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 证明与归纳\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一组测试说明样例通过，证明说明在明确前提下所有允许的情形都成立。学会把每一步的依据写出来。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"计算机理论 · 第 03 关；基础主线的并行选修\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"01–02；选读代码时先学 C 的循环。\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开形式化证明助手、超限归纳、完整 Hoare 逻辑。\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"先拆结论，再选方法\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"要证明一个断言，先写出对象范围、假设和目标。「存在」可尝试给出见证；「所有」应取任意对象；「当且仅当」要检查两个方向。反驳全称断言只需一个合法反例，但反驳存在断言要排除所有候选。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"直接证明从假设出发推出结论；逆否证明改证 \"},{\"t\":\"code\",\"v\":\"¬Q → ¬P\"},{\"t\":\"text\",\"v\":\"；反证法假定目标不成立，再推出矛盾。分类讨论必须覆盖所有情况，不能把最难的分支漏掉。双重计数则从两个角度数同一集合，后面的握手定理会再次使用。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题与证明工具\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：直接与逆否\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若整数 a、b 都能被 3 整除，令 \"},{\"t\":\"code\",\"v\":\"a=3r\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"b=3s\"},{\"t\":\"text\",\"v\":\"，则 \"},{\"t\":\"code\",\"v\":\"a+b=3(r+s)\"},{\"t\":\"text\",\"v\":\"，因此和也能被 3 整除。这是展开定义的直接证明。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"证明「若整数 n² 为奇数，则 n 为奇数」可改证逆否：若 n 为偶数，写 \"},{\"t\":\"code\",\"v\":\"n=2k\"},{\"t\":\"text\",\"v\":\"，则 \"},{\"t\":\"code\",\"v\":\"n²=4k²=2(2k²)\"},{\"t\":\"text\",\"v\":\" 为偶数。不要只检查几个平方，也不要把「n 为奇数推出 n² 为奇数」当成原结论的证明。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"普通归纳：一小步怎样覆盖无限多项\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"设要证对所有整数 \"},{\"t\":\"code\",\"v\":\"n ≥ n₀\"},{\"t\":\"text\",\"v\":\" 都成立的 P(n)：\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"证明基例 P(n₀)。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"取任意 \"},{\"t\":\"code\",\"v\":\"k ≥ n₀\"},{\"t\":\"text\",\"v\":\"，在假设 P(k) 的前提下证明 P(k+1)。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"由归纳原理得出对所有 \"},{\"t\":\"code\",\"v\":\"n ≥ n₀\"},{\"t\":\"text\",\"v\":\" 成立。\"}],\"n\":3}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"例如一个日志缓冲区第 i 次写入 \"},{\"t\":\"code\",\"v\":\"3i+1\"},{\"t\":\"text\",\"v\":\" 字节，i 从 0 开始。理想数学模型下，写 n 次的总字节数为 \"},{\"t\":\"code\",\"v\":\"S(n)=n(3n−1)/2\"},{\"t\":\"text\",\"v\":\"。基例 \"},{\"t\":\"code\",\"v\":\"S(0)=0\"},{\"t\":\"text\",\"v\":\"；假设 k 次成立，再写 \"},{\"t\":\"code\",\"v\":\"3k+1\"},{\"t\":\"text\",\"v\":\" 字节，总数为 \"},{\"t\":\"code\",\"v\":\"k(3k−1)/2+3k+1=(k+1)(3k+2)/2\"},{\"t\":\"text\",\"v\":\"，正是目标公式。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这是数学整数上的结论；实现时还要检查机器整数溢出和分配失败，不能把抽象证明直接当成 C 内存安全证明。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：强归纳与拆分合并\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若合并器每次只能把两个非空包合成一个包，从 n 个初始包得到一个包，任意完整二叉合并方案都恰有 \"},{\"t\":\"code\",\"v\":\"n−1\"},{\"t\":\"text\",\"v\":\" 次合并。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"以 n 强归纳。n 为 1 时无需合并。n 大于 1 时，最后一次操作合并了两个子方案，它们分别包含 a、b 个初始包，\"},{\"t\":\"code\",\"v\":\"a+b=n\"},{\"t\":\"text\",\"v\":\" 且 \"},{\"t\":\"code\",\"v\":\"1 ≤ a,b \\u003c n\"},{\"t\":\"text\",\"v\":\"。由强归纳假设，前两部分分别用了 \"},{\"t\":\"code\",\"v\":\"a−1\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"b−1\"},{\"t\":\"text\",\"v\":\" 次，加最后一次，总数为 \"},{\"t\":\"code\",\"v\":\"n−1\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"强归纳允许使用此前所有更小规模的结论，不只是 P(n−1)；它与普通归纳在自然数上证明能力相同。这里须说明 a、b 确实更小，且子方案满足原题条件。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"良序与最小反例\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"良序原理\"}]},{\"t\":\"text\",\"v\":\"：每个非空自然数子集都有最小元素；本专题自然数包含 0。不能把它套到正实数上，因为正实数集合没有最小正数。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"上面的字节公式也可用最小反例证明：若反例存在，取最小反例 m。基例保证 \"},{\"t\":\"code\",\"v\":\"m>0\"},{\"t\":\"text\",\"v\":\"；m−1 不可能是反例，故可用公式计算前 m−1 次，再加 \"},{\"t\":\"code\",\"v\":\"3m−2\"},{\"t\":\"text\",\"v\":\"，推出第 m 次也满足公式，矛盾。最小反例、强归纳、普通归纳在此语境下互相对应，并不是三种相互冲突的数学规则。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"不变式和终止性要分开\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"考虑数学伪代码：从 \"},{\"t\":\"code\",\"v\":\"i=0, s=0\"},{\"t\":\"text\",\"v\":\" 开始，当 \"},{\"t\":\"code\",\"v\":\"i\\u003cn\"},{\"t\":\"text\",\"v\":\" 时依次执行 \"},{\"t\":\"code\",\"v\":\"s=s+3i+1\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"i=i+1\"},{\"t\":\"text\",\"v\":\"。循环不变式是「完成 i 次后，\"},{\"t\":\"code\",\"v\":\"s=i(3i−1)/2\"},{\"t\":\"text\",\"v\":\"，且 \"},{\"t\":\"code\",\"v\":\"0≤i≤n\"},{\"t\":\"text\",\"v\":\"」。\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"初始化\"}]},{\"t\":\"text\",\"v\":\"：i 为 0 时成立。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"保持\"}]},{\"t\":\"text\",\"v\":\"：按普通归纳的代数计算，一轮后仍成立。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"退出后\"}]},{\"t\":\"text\",\"v\":\"：i 等于 n，所以 s 是目标总数。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"终止\"}]},{\"t\":\"text\",\"v\":\"：非负整数 \"},{\"t\":\"code\",\"v\":\"n−i\"},{\"t\":\"text\",\"v\":\" 每轮严格减少，不能无限下降。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"前三点证明「如果停止则结果正确」，再补终止性才得到总正确性。一个过程即使保持不变式，也可能永远不退出。后续 \"},{\"t\":\"link\",\"v\":\"最短路证明\",\"href\":\"../11-shortest-path-proofs/\"},{\"t\":\"text\",\"v\":\" 会重复这套框架；C 调试工具仍回 \"},{\"t\":\"link\",\"v\":\"工具与调试\",\"href\":\"../../programming-basics/04-tools-debugging/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"常见误区\",\"id\":\"h-9\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"归纳假设不能直接假设正在证明的 P(k+1)。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"从「某个 k 成立」不能跳到「任意 k 都成立」。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"归纳步如果一次跳 2，就必须分别覆盖两个起始奇偶链。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"「每轮更小」还要说明下降量所在集合良基；正实数可无限减半。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-10\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能为一个简单结论写完整假设、推理和收尾。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能指出归纳基例、归纳假设的适用规模。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能把算法的部分正确性与终止性分开论证。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-11\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"证明：若整数 a、b 均为偶数，则 \"},{\"t\":\"code\",\"v\":\"a−b\"},{\"t\":\"text\",\"v\":\" 为偶数。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"一个计数器起始为 5，每次增加 4。用归纳证明第 n 次操作后为 \"},{\"t\":\"code\",\"v\":\"5+4n\"},{\"t\":\"text\",\"v\":\"，范围为 \"},{\"t\":\"code\",\"v\":\"n≥0\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"二叉合并例子中，为什么只假设规模 n−1 的结论未必能直接完成那一步？为什么允许空子方案会破坏上述证明写法？\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"过程不断把正实数 x 替换成 x/2。仅凭「严格下降且有下界 0」，能证明有限次后到 0 吗？\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"令 \"},{\"t\":\"code\",\"v\":\"a=2u\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"b=2v\"},{\"t\":\"text\",\"v\":\"，则 \"},{\"t\":\"code\",\"v\":\"a−b=2(u−v)\"},{\"t\":\"text\",\"v\":\"；u−v 是整数，所以差为偶数。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"n 为 0 时是 5。假设 k 次后为 \"},{\"t\":\"code\",\"v\":\"5+4k\"},{\"t\":\"text\",\"v\":\"，再增加 4 得 \"},{\"t\":\"code\",\"v\":\"5+4(k+1)\"},{\"t\":\"text\",\"v\":\"，故对所有非负整数成立。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"子规模 a、b 可能都不等于 n−1，强归纳假设可同时覆盖它们。若允许某侧包含 0 个初始包，另一侧可能仍为 n，不能援引「更小规模」，并且问题本身的操作规则也已改变。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"不能。数学实数模型下，每个有限步后仍为正，只是趋近 0；「非负整数严格下降」与「有下界的实数严格下降」不是同一个终止依据。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-12\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018 版第 1、2、5、6 章，证明、良序、归纳、不变式与终止性。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Book of Proof\",\"href\":\"https://richardhammack.github.io/BookOfProof/\"},{\"t\":\"text\",\"v\":\" — 直接、逆否、反证与归纳的完整入门材料。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Proof by Induction\",\"href\":\"https://vertex.degree/appendix/induction.html\"},{\"t\":\"text\",\"v\":\" — 图结构的删除与重建视角；本页日志与合并例题为原创讲解。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：集合、关系与函数\",\"href\":\"../02-sets-relations-functions/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：组合计数与递推\",\"href\":\"../04-counting-recurrences/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"先拆结论，再选方法\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"小例题与证明工具\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"例一：直接与逆否\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"普通归纳：一小步怎样覆盖无限多项\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"例二：强归纳与拆分合并\"},{\"id\":\"h-7\",\"level\":3,\"text\":\"良序与最小反例\"},{\"id\":\"h-8\",\"level\":3,\"text\":\"不变式和终止性要分开\"},{\"id\":\"h-9\",\"level\":2,\"text\":\"常见误区\"},{\"id\":\"h-10\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-11\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/04-counting-recurrences\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 组合计数与递推\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"计数首先是明确对象：顺序算不算区别、能不能重复、情况有没有重叠。公式只是这些选择的结果。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"计算机理论 · 第 04 关；基础主线的并行选修\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"01–03；整数运算。\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开生成函数、概率论、渐近递推求解大全。\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"从一条构建流水线计数\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"测试任务可选 3 种架构和 2 种模式，每一种架构都支持两种模式，因此有 \"},{\"t\":\"code\",\"v\":\"3×2=6\"},{\"t\":\"text\",\"v\":\" 种任务配置。若再额外提供 4 种与这些配置互不相同的诊断任务，总数为 \"},{\"t\":\"code\",\"v\":\"6+4=10\"},{\"t\":\"text\",\"v\":\"。这里相乘不是概率独立，而是每一步可选数量满足条件。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"加法、乘法与去重\",\"id\":\"h-4\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"加法原理\"}]},{\"t\":\"text\",\"v\":\"：互不相交的有限情况数可以相加。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"乘法原理\"}]},{\"t\":\"text\",\"v\":\"：分步选择，若第一步有 a 种且每种都对应 b 种后续，总数是 ab；后续数量不同时要分支求和。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"排列\"}]},{\"t\":\"text\",\"v\":\"：从 n 个不同对象中无重复地有序选 k 个，为 \"},{\"t\":\"code\",\"v\":\"n!/(n−k)!\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"组合\"}]},{\"t\":\"text\",\"v\":\"：无序选 k 个，为 \"},{\"t\":\"code\",\"v\":\"C(n,k)=n!/(k!(n−k)!)\"},{\"t\":\"text\",\"v\":\"，其中 \"},{\"t\":\"code\",\"v\":\"0≤k≤n\"},{\"t\":\"text\",\"v\":\"。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"code\",\"v\":\"0!=1\"},{\"t\":\"text\",\"v\":\"；空集合有且仅有一个空子集，所以 \"},{\"t\":\"code\",\"v\":\"C(n,0)=1\"},{\"t\":\"text\",\"v\":\"。把排列除以 k! 得组合，是因为每个 k 元子集恰好对应 k! 个排列；不能看到「有重复」就随便除以一个数。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"鸽巢原理与容斥\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"把 N 个对象放到 k 个盒子里，\"},{\"t\":\"code\",\"v\":\"k≥1\"},{\"t\":\"text\",\"v\":\"，至少有一个盒子装了不少于 \"},{\"t\":\"code\",\"v\":\"⌈N/k⌉\"},{\"t\":\"text\",\"v\":\" 个。反证很直接：如果每盒都少于这个数，总容量就不够 N。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若两个任务集合 A、B 有重叠，则 \"},{\"t\":\"code\",\"v\":\"|A∪B|=|A|+|B|−|A∩B|\"},{\"t\":\"text\",\"v\":\"。三个集合时，先加单集、减去三个两两交集，再加回三重交集；三重交集里的对象被先加 3 次、再减 3 次，因此还要加 1 次。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"递推：先按最后一步分组\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"设一条流水线的步骤序列仅使用符号 A、B，禁止连续出现两个 B。令 f(n) 为长度 n 的合法序列数量。n 为 0 时有一个空序列，故 \"},{\"t\":\"code\",\"v\":\"f(0)=1\"},{\"t\":\"text\",\"v\":\"；\"},{\"t\":\"code\",\"v\":\"f(1)=2\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"当 \"},{\"t\":\"code\",\"v\":\"n≥2\"},{\"t\":\"text\",\"v\":\"，合法序列若以 A 结尾，删除 A 后有 f(n−1) 种；若以 B 结尾，前一个必须是 A，删除末尾 AB 后有 f(n−2) 种。这两个情况不重叠且覆盖全部，因此 \"},{\"t\":\"code\",\"v\":\"f(n)=f(n−1)+f(n−2)\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这也说明为什么初值与递推同样重要。后面 \"},{\"t\":\"link\",\"v\":\"DAG\",\"href\":\"../10-digraphs-dag/\"},{\"t\":\"text\",\"v\":\" 中的路径计数是把「长度更小」推广成「前驱先算」。本关不要求掌握递推闭式或生成函数。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题\",\"id\":\"h-7\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：有序岗位与无序小组\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"从 6 个互不相同的测试模块中选 2 个分别作为主检查、复核检查，不能重复选同一模块，有 \"},{\"t\":\"code\",\"v\":\"6×5=30\"},{\"t\":\"text\",\"v\":\" 种。若只是选一个双模块检查组、角色没有区别，则有 \"},{\"t\":\"code\",\"v\":\"C(6,2)=15\"},{\"t\":\"text\",\"v\":\" 种。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"注意对象是模块标识，不是运行结果；两个模块恰好输出相同，也不会自动变成同一个选择。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：重叠标记与必然冲突\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"28 条测试中，16 条有标签 A，11 条有标签 B，其中 6 条两种都有。至少有一种标签的测试是 \"},{\"t\":\"code\",\"v\":\"16+11−6=21\"},{\"t\":\"text\",\"v\":\" 条，没有标签的是 7 条。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"另有 19 个缓存键映射到 6 个桶。至少一个桶含 \"},{\"t\":\"code\",\"v\":\"⌈19/6⌉=4\"},{\"t\":\"text\",\"v\":\" 个键，这是确定性的下界，不依赖哈希函数是否均匀。它不告诉我们具体哪个桶，也不能推出恰好只有 4 个。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例三：枚举小规模递推\",\"id\":\"h-10\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"长度 3 的合法序列为 \"},{\"t\":\"code\",\"v\":\"AAA\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"AAB\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"ABA\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"BAA\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"BAB\"},{\"t\":\"text\",\"v\":\"，共 5 个。长度 4、5、6 则依次为 8、13、21。枚举可发现递推写错，但一般结论来自前面不重不漏的分类证明，而不是只检查到长度 6。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-11\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能在使用组合公式前交代顺序和重复规则。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能指出两类计数是否重叠，并正确使用容斥。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能从递推的分类规则解释初值与适用范围。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-12\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"从 7 个插件中选 3 个进行无序兼容测试，不重复，多少种？若还要决定这 3 个的加载顺序，多少种？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"31 个构建任务分到 5 台机器，证明至少一台分到 7 个；这是否保证负载时间均衡？\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"40 条记录中，A、B、C 标签分别出现 20、18、15 次，两两交集分别为 8、7、6，三重交集为 3。至少有一个标签的记录数是多少？\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"仍禁止连续 B。计算 f(2)、f(3)、f(4)；解释为什么不能统一写成 \"},{\"t\":\"code\",\"v\":\"f(n)=2f(n−1)\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"无序为 \"},{\"t\":\"code\",\"v\":\"C(7,3)=35\"},{\"t\":\"text\",\"v\":\"；每个三元素集合有 \"},{\"t\":\"code\",\"v\":\"3!=6\"},{\"t\":\"text\",\"v\":\" 种加载顺序，共 210 种。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"若每台最多 6 个，总共最多 30 个，与 31 矛盾。只保证数量下界；任务耗时可能不同，不保证时间负载均衡。\"}],\"n\":2},{\"inlines\":[{\"t\":\"code\",\"v\":\"20+18+15−8−7−6+3=35\"},{\"t\":\"text\",\"v\":\" 条；因此无标签为 5 条。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"依次为 3、5、8。尾部为 B 的序列不能再追加 B，并非每种旧序列都恰有两种合法扩展。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-13\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018 版第 15 章讲计数、鸽巢与容斥，第 22 章讲递推。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"MIT Mathematics for Computer Science 阅读入口\",\"href\":\"https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-spring-2015/pages/readings/\"},{\"t\":\"text\",\"v\":\" — 对照 Counting 单元做额外练习，不必先读概率单元。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：目录\",\"href\":\"https://vertex.degree/contents.html\"},{\"t\":\"text\",\"v\":\" — 图的边、树、匹配都反复使用计数；本页构建和标签例题独立编写，不改写该书谜题。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：证明与归纳\",\"href\":\"../03-proofs-induction/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：图的建模与度数\",\"href\":\"../05-graphs-degrees/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"从一条构建流水线计数\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"加法、乘法与去重\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"鸽巢原理与容斥\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"递推：先按最后一步分组\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"小例题\"},{\"id\":\"h-8\",\"level\":3,\"text\":\"例一：有序岗位与无序小组\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例二：重叠标记与必然冲突\"},{\"id\":\"h-10\",\"level\":3,\"text\":\"例三：枚举小规模递推\"},{\"id\":\"h-11\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-13\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/05-graphs-degrees\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"理论基础\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 图的建模与度数\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"图的重点不是点画在哪里，而是哪些对象允许联系。先建立模型，再用度数和不变量检查方案能否存在。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"理论基础 · 第 05 章。旧笔记里的「计算机理论」仍指专题页\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"本页写完定义和证明。04 的组合与鸽巢、02 的双射只是按需对照，不是进门条件\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开图存储实现、Havel–Hakimi 完整算法、谱图论。章末任务和自测可以不做\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"原创谜题：兼容接口够不够\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"6 个测试模块 A–F 之间提供双向兼容接口，不能自己连自己，同一对模块最多连一次。需求写成度数表：A 要连 3 个模块，B、C 各连 2 个，D、E、F 各连 1 个。这种方案能存在吗？如果把 F 的要求改成 2，又会怎样？\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"先把「接口」抽象为一条边，忽略模块的摆放位置、源文件大小和机器名称。图模型只保留这道题需要的关系；真实接口若有方向或重复通道，应换模型，不能偷偷继续套简单无向图的结论。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"本专题的默认约定\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"除非另说，图都是\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"有限简单无向图\"}]},{\"t\":\"text\",\"v\":\" \"},{\"t\":\"code\",\"v\":\"G=(V,E)\"},{\"t\":\"text\",\"v\":\"：V 是有限顶点集，每条边是两个不同顶点组成的无序对，没有自环和重边。边 AB 与 BA 是同一条；有向图则不同，放到 \"},{\"t\":\"link\",\"v\":\"第 10 关\",\"href\":\"../10-digraphs-dag/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"令 \"},{\"t\":\"code\",\"v\":\"n=|V|\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"m=|E|\"},{\"t\":\"text\",\"v\":\"。相邻顶点之间有边；边与它的端点关联。顶点 v 的度数 deg(v) 是与它关联的边数；度为 0 的顶点叫孤立点，度为 1 的叫叶子。叶子不是「画在最外面」的点。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"完全图 Kₙ 的任意两点都有边，因此有 \"},{\"t\":\"code\",\"v\":\"C(n,2)=n(n−1)/2\"},{\"t\":\"text\",\"v\":\" 条边；任何 n 顶点简单图都不超过这个数。补图在同一顶点集上，把原来有边的位置去掉、原来没边的位置补上；故 \"},{\"t\":\"code\",\"v\":\"deg_G(v)+deg_补图(v)=n−1\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"握手定理：数同一件事两次\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"定理\"}]},{\"t\":\"text\",\"v\":\"：有限无向图的度数总和等于边数的两倍，即 \"},{\"t\":\"code\",\"v\":\"Σdeg(v)=2m\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"证明时数的是「边的一端」：从顶点出发数，一共是度数和；从边出发数，每条边贡献两个端点，一共是 2m。因此奇度顶点数必为偶数，否则度数和会是奇数。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"结论也能推广到允许重边和自环的无向多重图，但此时自环对度数贡献 2。本专题如未声明，仍只使用简单图，避免混淆最大边数等限制。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"偶数和只说明方案没有被握手定理立刻否定，它不是充分条件。4 个顶点的度数 \"},{\"t\":\"code\",\"v\":\"3,3,0,0\"},{\"t\":\"text\",\"v\":\" 和为 6，但度为 3 的点必须连到那两个被要求度为 0 的点，做不到。例一把同一事实用在改过的接口表上。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"有向图另算。每条弧贡献 1 次出度和 1 次入度，自环也是如此，所以全体出度之和与全体入度之和都等于弧数。因此「奇数出度的顶点有偶数个」并不成立。例三把同一份记录按多重图、简单图和有向图各算一遍。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"同度定理。\"}]},{\"t\":\"text\",\"v\":\" 至少有 2 个顶点的有限简单无向图里，总有两个不同顶点的度数相等。每个度数都属于 \"},{\"t\":\"code\",\"v\":\"0,1,…,n−1\"},{\"t\":\"text\",\"v\":\"，这是 n 个数，但 0 和 n−1 不能同时出现：度为 n−1 的点与所有其他点相邻，就没有孤立点；有孤立点，就没有点能连到所有人。这两个数也可以都不出现，那时可用的数值更少。于是 n 个顶点最多占用 n−1 种度数，必有两个相同。允许重边、只看出度、或只有 1 个顶点时，这个结论可以失败。例四是逐步书写，并给出这三种反例。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"子图、诱导子图与同构\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"子图可删除顶点、删除边；给定顶点集 S 的\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"诱导子图\"}]},{\"t\":\"text\",\"v\":\"则必须保留原图在 S 内所有边。例如 A、B、C 原来形成三角形，保留三点但只取 AB、BC 是子图，不是这三点的诱导子图。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"图同构是顶点之间的一个双射：每个顶点恰好对应到一个顶点，并且可以反过来，同时保持邻接与不邻接。它表达「换名字后是同一个连接结构」。顶点数、边数、度数多重集、连通性都是同构不变量，但这些不变量相同并不自动给出同构。例二用一个 8 点环和两个分开的 4 点环说明这一点。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若简单图与自己的补图同构，两边边数相等，所以 \"},{\"t\":\"code\",\"v\":\"m=n(n−1)/4\"},{\"t\":\"text\",\"v\":\" 必须是整数。n 与 n−1 是连续整数，它们的积要被 4 整除，因此 n 除以 4 的余数只能是 0 或 1。n=6 时 \"},{\"t\":\"code\",\"v\":\"C(6,2)=15\"},{\"t\":\"text\",\"v\":\" 是奇数，不能平分，不可能自补。边数刚好一半仍然只是必要条件。路和星形是否自补，留在分层练习里核对映射，不在这里把答案先写完。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"图怎样用邻接矩阵或邻接表存进 C，已在 \"},{\"t\":\"link\",\"v\":\"数据结构与算法\",\"href\":\"../../cs-basics/06-data-structures-algorithms/\"},{\"t\":\"text\",\"v\":\" 中介绍；本页不重复写容器，重点是模型和必要条件。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题\",\"id\":\"h-7\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：构造与排除是两种任务\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"要求度数为 \"},{\"t\":\"code\",\"v\":\"3,2,2,1,1,1\"},{\"t\":\"text\",\"v\":\" 时，和为 10，需要 5 条边；一种具体方案为 \"},{\"t\":\"code\",\"v\":\"AB, AC, AD, BE, CF\"},{\"t\":\"text\",\"v\":\"。逐点数一遍即可得到全部需求。这既检查必要条件，也给了存在性的见证。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若把 F 改为 2，度数和变成 11，是奇数，握手定理立即排除。\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"偶数和只是必要条件\"}]},{\"t\":\"text\",\"v\":\"：例如 4 点度数为 \"},{\"t\":\"code\",\"v\":\"3,3,0,0\"},{\"t\":\"text\",\"v\":\"，和虽为 6，却不可能，因为度为 3 的点必须邻接那两个被要求度为 0 的点。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：度数一样也未必同构\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"图甲是 8 个顶点首尾相接的单个环；图乙是两个互不相连的 4 点环。两者都有 8 点、8 边，每点度为 2。但甲连通、乙不连通，所以不存在保持邻接的重命名。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"不变量特别适合\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"证明不可能\"}]},{\"t\":\"text\",\"v\":\"。若要证明同构存在，最可靠的入门方法是直接列出映射，再检查所有边与非边。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例三：同一份接口记录，换三种模型\",\"id\":\"h-10\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一份连接记录写着：A 与 B 之间有两条独立通道，B 与 C 有一条，C 有一条回环自检通道，D 尚未接入。问题不在算术，而在于先选定模型，再数度数。\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"模型\"}],[{\"t\":\"text\",\"v\":\"边\"}],[{\"t\":\"text\",\"v\":\"各点度数\"}],[{\"t\":\"text\",\"v\":\"核对\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"无向多重图，自环计 2\"}],[{\"t\":\"text\",\"v\":\"AB、AB、BC、CC\"}],[{\"t\":\"text\",\"v\":\"A=2，B=3，C=3，D=0\"}],[{\"t\":\"text\",\"v\":\"度和 8，边数 4\"}]],[[{\"t\":\"text\",\"v\":\"投影成简单图\"}],[{\"t\":\"text\",\"v\":\"AB、BC\"}],[{\"t\":\"text\",\"v\":\"A=1，B=2，C=1，D=0\"}],[{\"t\":\"text\",\"v\":\"度和 4，边数 2\"}]],[[{\"t\":\"text\",\"v\":\"有向图\"}],[{\"t\":\"text\",\"v\":\"A→B、A→B、B→C、C→C\"}],[{\"t\":\"text\",\"v\":\"出度 A=2，B=1，C=1，D=0；入度 A=0，B=2，C=2，D=0\"}],[{\"t\":\"text\",\"v\":\"出度和、入度和都为 4\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"逐步看三处细节：\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"多重图里，自环的两个端点都落在 C 上，「数边的端点」时就该数两次，所以 C 的度是 1+2=3。若只数一次，度和变成 7，是奇数，立刻与 \"},{\"t\":\"code\",\"v\":\"2m\"},{\"t\":\"text\",\"v\":\" 矛盾——矛盾暴露的是约定错误，而不是握手定理失效。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"投影成简单图会合并重边、删去自环，度数随之改变：A 从 2 变 1，B 从 3 变 2。奇度顶点从 \"},{\"t\":\"code\",\"v\":\"{B,C}\"},{\"t\":\"text\",\"v\":\" 变成 \"},{\"t\":\"code\",\"v\":\"{A,C}\"},{\"t\":\"text\",\"v\":\"；两种模型都满足「奇度顶点有偶数个」，但不是同一批点。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"有向图中每条边恰好贡献一次出度和一次入度，所以出度和、入度和各等于 m；自环 C→C 也同时贡献一次出度和一次入度。入度与出度相加，就回到多重图里的度数。\"}],\"n\":3}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"零度顶点 D 计入 n，但对度和贡献 0。后面讨论连通、欧拉条件时，「有没有孤立点」会成为必须单独说明的前提。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例四：简单图里必有两点度数相同\",\"id\":\"h-11\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"命题\"}]},{\"t\":\"text\",\"v\":\"：至少有 2 个顶点的有限简单无向图中，一定有两个不同顶点的度数相等。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"先看直觉：n 个点的度数只能取 \"},{\"t\":\"code\",\"v\":\"0,1,…,n−1\"},{\"t\":\"text\",\"v\":\" 这 n 个值，似乎每个点刚好可以各占一个值。严格证明的关键是：0 和 n−1 不能同时出现，但两个都可以不出现。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"简单图里，一个点最多与其余 n−1 个点各连一条边，所以度数属于 \"},{\"t\":\"code\",\"v\":\"{0,1,…,n−1}\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"若某点度为 n−1，它与所有其他点相邻，于是没有任何点度为 0；反过来，若某点度为 0，就没有点能达到 n−1。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"因此这 n 个度数不能同时含有 0 和 n−1；两个都可以不出现。用到的数值至多有 n−1 种，两个都不出现时更少。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"由 \"},{\"t\":\"link\",\"v\":\"鸽巢原理\",\"href\":\"../04-counting-recurrences/\"},{\"t\":\"text\",\"v\":\"，至少两个顶点的度数相同。\"}],\"n\":4}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"前提逐条都在起作用，换掉任何一条都可能失败：\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"允许重边\"}]},{\"t\":\"text\",\"v\":\"：三点 A、B、C，边为 AB、AC、AC，度数为 3、1、2，两两不同；第 1 步的上界 n−1 不再成立。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"有向图只看出度\"}]},{\"t\":\"text\",\"v\":\"：A→B、A→C、B→C 的出度为 2、1、0，两两不同；「有人出度 n−1 就没人出度 0」在有向图中不成立，因为指向别人不等于被别人指向。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"只有 1 个顶点\"}]},{\"t\":\"text\",\"v\":\"：没有「两个不同顶点」可比较。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"把结论读成「每个度数值都恰好有两个点」也是错的：它只保证至少一对相等。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-12\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能交代图中的顶点、边及是否有向、允许自环或重边。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能用双重计数证明握手定理，而不只背结论。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能区分必要条件检查与存在性构造。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能在多重图、简单图、有向图三种约定下正确计算度数并核对握手关系。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能说出一个结论依赖的每条前提，并为去掉前提给出反例。\"}]}]},{\"t\":\"h\",\"level\":3,\"text\":\"分层练习\",\"id\":\"h-13\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"【入门】有向调用图的顶点为 P、Q、R、S，边为 \"},{\"t\":\"code\",\"v\":\"P→Q, P→R, Q→R, R→P, S→P\"},{\"t\":\"text\",\"v\":\"。求各点出度、入度，核对两种和；出度为奇数的顶点有几个？这与「奇度顶点有偶数个」矛盾吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"【进阶】度数要求为 \"},{\"t\":\"code\",\"v\":\"4,4,4,1,1\"},{\"t\":\"text\",\"v\":\"。它的度和是偶数，能否由 5 个顶点的简单图实现？若允许重边但不允许自环呢？给出证明或构造。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"【进阶】一个冲突图若与它的补图同构，称为自补图。(a) 证明 6 个顶点的简单图不可能自补。(b) 4 个顶点、3 条边的图中，路 \"},{\"t\":\"code\",\"v\":\"a–b–c–d\"},{\"t\":\"text\",\"v\":\" 与星形（一点连其余三点）哪个自补？由此说明「边数满足条件」只是必要条件。\"}],\"n\":3}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"出度：P=2，Q=1，R=1，S=1，和为 5；入度：P=2（来自 R、S），Q=1，R=2，S=0，和为 5，都等于边数 5。出度为奇数的点是 Q、R、S，共 3 个。这不矛盾：「奇度顶点有偶数个」来自无向度数和等于 \"},{\"t\":\"code\",\"v\":\"2m\"},{\"t\":\"text\",\"v\":\"，而出度和只等于 m，可以是奇数。忽略方向后的度数为 P=4，Q=2，R=3，S=1（P、R 之间有两条反向边，底层是重边），度和 10，奇度点 R、S 恰好 2 个。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"简单图不可能。5 个顶点时度为 4 意味着与其余 4 点都相邻；有三个这样的点，那么两个度为 1 的点各自至少与这三点相邻，度数至少为 3，矛盾。偶数度和只是必要条件。允许重边时可以实现：设度为 4 的是 A、B、C，度为 1 的是 D、E，取边 AD、BE、AB、AC、AC、BC、BC，共 7 条，逐点核对 A、B、C 均为 4，D、E 均为 1，度和 14。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"(a) 同构保持边数，补图边数为 \"},{\"t\":\"code\",\"v\":\"C(n,2)−m\"},{\"t\":\"text\",\"v\":\"，故 \"},{\"t\":\"code\",\"v\":\"m=C(n,2)/2=n(n−1)/4\"},{\"t\":\"text\",\"v\":\" 必须是整数。n=6 时 \"},{\"t\":\"code\",\"v\":\"C(6,2)=15\"},{\"t\":\"text\",\"v\":\" 是奇数，不能平分，所以不可能自补。一般地 n 除以 4 余 0 或 1 才可能。(b) 路自补：补图边为 ac、ad、bd，恰好是路 \"},{\"t\":\"code\",\"v\":\"c–a–d–b\"},{\"t\":\"text\",\"v\":\"，映射 a↦c、b↦a、c↦d、d↦b 保持邻接与不邻接。星形不自补：它的度数多重集是 \"},{\"t\":\"code\",\"v\":\"{3,1,1,1}\"},{\"t\":\"text\",\"v\":\"，补图是三角形加一个孤立点，度数多重集 \"},{\"t\":\"code\",\"v\":\"{2,2,2,0}\"},{\"t\":\"text\",\"v\":\"，不变量不同。两者都有 3 条边，说明边数条件不够。\"}],\"n\":3}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-14\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"一个 9 顶点兼容图，要求度数依次为 \"},{\"t\":\"code\",\"v\":\"5,4,3,3,2,2,2,2,2\"},{\"t\":\"text\",\"v\":\"，可能吗？给出理由。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"一个 6 顶点简单图中，某点度为 4，它在补图中的度是多少？补图总边数和原图总边数之和是多少？\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"若只知道两个图度数多重集相同，就宣布它们同构，错在哪里？给一个本页之外的不同顶点数实例。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"在图 \"},{\"t\":\"code\",\"v\":\"V={A,B,C,D}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"E={AB,AC,BC,CD}\"},{\"t\":\"text\",\"v\":\" 中，取顶点 \"},{\"t\":\"code\",\"v\":\"{A,B,C}\"},{\"t\":\"text\",\"v\":\"：诱导子图有几条边？只取 AB、BC 的对象是什么？\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"不存在，度数和 \"},{\"t\":\"code\",\"v\":\"5+4+3+3+2+2+2+2+2=25\"},{\"t\":\"text\",\"v\":\" 为奇数，不能等于 2m。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"度为 \"},{\"t\":\"code\",\"v\":\"6−1−4=1\"},{\"t\":\"text\",\"v\":\"；总边数之和为 \"},{\"t\":\"code\",\"v\":\"C(6,2)=15\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"度数不记录整个连接方式。例如 10 点单环与互不相连的 4 点环加 6 点环，均为 10 点、10 边且每点度为 2，却因连通性不同而不同构。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"诱导子图有 AB、AC、BC 共 3 条边。只取 AB、BC 是原图的子图，但不是指定顶点集的诱导子图。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-15\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Modeling Problems with Graphs\",\"href\":\"https://vertex.degree/beginning/examples.html\"},{\"t\":\"text\",\"v\":\" — Mikhail Lavrov 从问题中挑出顶点和边；本页使用独立设计的模块兼容需求，不复用原书谜题。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：The Degree of a Vertex\",\"href\":\"https://vertex.degree/beginning/degrees.html\"},{\"t\":\"text\",\"v\":\" — 度数、握手定理及其应用。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Isomorphisms and Subgraphs\",\"href\":\"https://vertex.degree/beginning/isomorphism.html\"},{\"t\":\"text\",\"v\":\" — 同构、不变量与子图。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018 版第 12 章，简单图定义与基础结论。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Euler Tours\",\"href\":\"https://vertex.degree/degrees/euler.html\"},{\"t\":\"text\",\"v\":\" — 在多重图语言下处理自环，明确自环对度数贡献 2；本页例三的三模型对照为原创。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science：Pigeonhole Principle\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018 版 15.8 节鸽巢原理，配合 12.2.1 节握手引理，用于例四的证明。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Princeton Algorithms：Undirected Graphs\",\"href\":\"https://algs4.cs.princeton.edu/41graph/\"},{\"t\":\"text\",\"v\":\" — 图数据类型允许自环与重边的约定，以及度数的程序化定义。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：组合计数与递推\",\"href\":\"../04-counting-recurrences/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 理论基础\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：路径、连通与遍历\",\"href\":\"../06-walks-connectivity-euler/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"原创谜题：兼容接口够不够\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"本专题的默认约定\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"握手定理：数同一件事两次\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"子图、诱导子图与同构\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"小例题\"},{\"id\":\"h-8\",\"level\":3,\"text\":\"例一：构造与排除是两种任务\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例二：度数一样也未必同构\"},{\"id\":\"h-10\",\"level\":3,\"text\":\"例三：同一份接口记录，换三种模型\"},{\"id\":\"h-11\",\"level\":3,\"text\":\"例四：简单图里必有两点度数相同\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-13\",\"level\":3,\"text\":\"分层练习\"},{\"id\":\"h-14\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-15\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/06-walks-connectivity-euler\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"理论基础\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 路径、连通与遍历\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"「不重复走边」和「不重复经过点」看似相近，实际是不同问题。严谨的路径语言会让条件一目了然。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"理论基础 · 第 06 章。旧笔记里的「计算机理论」仍指专题页\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"要先会 05 的度数，以及奇度顶点个数为偶数。03 的证明习惯是按需，不是进门条件\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开哈密顿充分条件大全、旅行商求解、点连通度进阶。章末任务和自测可以不做\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"原创谜题：每个接口只巡检一次\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"巡检图的边为 \"},{\"t\":\"code\",\"v\":\"AB, BC, CA, AD\"},{\"t\":\"text\",\"v\":\"，表示四条双向接口。巡检器能否从某模块出发，每条接口恰好通过一次？如果还要求回到起点呢？先明确要覆盖的是\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"边\"}]},{\"t\":\"text\",\"v\":\"，不是「每个模块只到一次」。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"游走、迹、路与圈\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"不同教材对中文「路径」用词不完全一致，本专题固定如下约定；英文术语可帮助核对。\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"名称\"}],[{\"t\":\"text\",\"v\":\"允许的重复\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"游走 walk\"}],[{\"t\":\"text\",\"v\":\"相邻顶点必须有边，顶点和边均可重复\"}]],[[{\"t\":\"text\",\"v\":\"迹 trail\"}],[{\"t\":\"text\",\"v\":\"不重复边，但可重复顶点\"}]],[[{\"t\":\"text\",\"v\":\"简单路 path\"}],[{\"t\":\"text\",\"v\":\"不重复顶点，因此也不重复边\"}]],[[{\"t\":\"text\",\"v\":\"闭游走\"}],[{\"t\":\"text\",\"v\":\"起点与终点相同\"}]],[[{\"t\":\"text\",\"v\":\"圈 cycle\"}],[{\"t\":\"text\",\"v\":\"长度至少为 3，除首尾相同外不重复顶点\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"长度按经过的边数计。单个顶点构成长为 0 的路；圈的顶点数与边数相同。一条游走若两次到达某个点，可删去两次到达之间的闭合段，仍连接原来的两端。每次删除使长度减少，最终得到简单路。因此「存在游走」与「存在简单路」在判断可达时等价。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"连通分量、桥与割点\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"无向图中「存在游走能到达」包含长度 0 的自达，满足自反、对称、传递，因而把 V 划分成连通分量。图非空且只有一个分量时叫连通。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"删除一条边若使连通分量数增加，该边叫桥；删除一个顶点及其关联边若使分量数增加，该点叫割点。圈上的边不是桥，因为被删边的两端仍能绕圈相连。实际网络的冗余要先明确故障对象是点还是边，二者不同。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"欧拉迹与欧拉回路\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"欧拉迹恰好使用每条边一次；起终点相同的叫欧拉回路。对至少含一条边的有限无向图：\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"有欧拉回路，当且仅当所有非零度顶点处于同一连通分量，且每个顶点度为偶数。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"有起终点不同的欧拉迹，当且仅当上述连通条件成立，且恰有两个奇度顶点；它们必须是两端。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"必要性来自配对：闭迹里，中间点每用掉一条进入的边，就要再配一条离开的边；开放迹的起终点各剩一条未配对边。这一句只解释「为什么度数必须是偶数」，还没有证明「偶度时走不到一半就停住」。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"充分性要看停住的那一刻。沿未用边往前走，允许重边，自环整条计 2。若停在不是本段起点的顶点 v，已经用掉的关联度数是奇数：经普通边进入的次数比离开的次数多 1，自环进出成对、只加偶数。v 原来的度是偶数，剩余度数仍是奇数，所以至少为 1，还能再走。起点处已用度数保持偶数，剩余可以降到 0；这时停住的是本段起点，走出的是闭迹。若还有未用边，由非零度部分连通，已走出的闭迹上必有一个仍有未用边的点，从那里再走一条闭迹并拼进去。每次消耗边，有限次后恰好用完。两个奇点时，可先增加一条连接它们的辅助边，允许形成重边；找到回路后切开这条辅助边，便得到原图的开放迹。例三是一次具体巡检，不要用「每进入一次都离开一次」代替上面这一步。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"有向图。\"}]},{\"t\":\"text\",\"v\":\" 弧有方向，自环同时记 1 次入度和 1 次出度。有向欧拉回路存在，当且仅当每个顶点入度等于出度，并且所有入度或出度不为 0 的顶点在忽略方向后属于同一个连通分量。必要性仍是配对，只是进入必须沿着弧。充分性只能顺着未用弧走，拼接方式和无向图相同。起终点不同的有向欧拉迹则改成：起点出度比入度多 1，终点入度比出度多 1，其余顶点平衡，连通性要求相同；添一条从终点指向起点的弧，就化成回路，再把这条弧切开。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"Euler Tours\",\"href\":\"https://vertex.degree/degrees/euler.html\"},{\"t\":\"text\",\"v\":\" 的推论用「除孤立点外弱连通，且每个顶点入度等于出度」表述回路。\"},{\"t\":\"link\",\"v\":\"Directed Graphs\",\"href\":\"https://algs4.cs.princeton.edu/42digraph/\"},{\"t\":\"text\",\"v\":\" 的习题则要求非零度顶点属于同一个强连通分量。在入度已经等于出度时，两者是同一范围：设 R 是从某个非零度顶点能到达的顶点集合。全体顶点平衡，所以跨出 R 的弧数等于跨入 R 的弧数。只要还有弧跨过边界，就会走到 R 外面，与 R 的定义矛盾。孤立点的入度和出度都是 0，可以留在这个分量之外。分层练习第 2 题是在用这个定理，不是在补定义。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若只有孤立点、但至少有一个顶点，约定长度 0 的游走已经覆盖全部空边集；本页不讨论没有顶点的空图的欧拉命名差异。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"哈密顿问题换成了遍点\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"哈密顿路经过每个顶点恰好一次；哈密顿圈除首尾外经过每点恰好一次，并返回起点。后者要求至少 3 个顶点。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"有哈密顿圈的图必须连通、每点度至少为 2，并且没有桥。但这些必要条件不能随便当成充分条件；哈密顿圈的存在性不是看奇偶度就能决定的。一般有限简单图的哈密顿圈判定是 NP 完全问题，精确定义在 \"},{\"t\":\"link\",\"v\":\"复杂度与归约\",\"href\":\"../14-complexity-reductions/\"},{\"t\":\"text\",\"v\":\" 中给出；这不等于所有小图都难，也不等于已经证明所有算法都慢。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"删点上界。\"}]},{\"t\":\"text\",\"v\":\" 若图有哈密顿圈，则删去任意 k 个顶点（1 ≤ k \\u003c n）后，剩下至多 k 个连通分量。本页的圈至少有 3 个顶点，所以上界从 n≥3 就成立，不必改成 n≥4。三角形删掉一个顶点后，剩下的两点仍有一条边，分量数是 1，没有超过 k。被删的点如果在圈上相邻，剩下的段数会少于 k，上界仍然只是「至多」。证明就三步：这 k 个点把圈切成若干段路，相邻两段之间至少夹着一个被删点，又因为圈绕回来，段数不超过 k；每一段内部连通；图的其余边只会把段连起来，不会把一段拆开。路的版本不绕回来，删 k 个点后至多 k+1 段。满足上界的图仍可能没有哈密顿圈。例四用蝶形图演示圈的版本，并说明它只是必要条件。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"和二部图有关的另一条界。\"}]},{\"t\":\"text\",\"v\":\" 顶点若能分成两侧、边只连接不同侧，沿圈就必须左右交替，长度不能是奇数。简单图里这样的圈最短是 4。因此二部图若有哈密顿圈，n 必须是偶数并且至少为 4，两侧的顶点数还要相等。3×3 网格可以这样染色，两侧是 5 和 4，n=9，所以没有哈密顿圈。这和删点上界是两条不同的必要条件，不要把 n≥4 写进删点引理。二部图的一般理论在 \"},{\"t\":\"link\",\"v\":\"二分图与匹配\",\"href\":\"../08-bipartite-matching/\"},{\"t\":\"text\",\"v\":\"，例四只把网格的染色算完。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题\",\"id\":\"h-8\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：巡检路线与回路障碍\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"code\",\"v\":\"D → A → B → C → A\"},{\"t\":\"text\",\"v\":\" 使用 AD、AB、BC、CA 各一次，是欧拉迹，但不是简单路，也不是欧拉回路。A 的度为 3、D 的度为 1，恰为两个奇点；这既解释起终点，也证明不能闭合。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"给图再加一个孤立顶点 Z，原路线仍覆盖全部边；但不能成为覆盖全部顶点的哈密顿路，因为 Z 无法加入。这说明欧拉条件为什么只要求非零度部分连通。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：所有度都够也不保证哈密顿圈\",\"id\":\"h-10\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"把两个 4 点环各挑一个点，用一条额外的桥连接。每点度至少为 2，整体也连通。若哈密顿圈跨桥进入另一侧，必须再跨桥才能回起点，但圈不能重复这条边，因此不存在哈密顿圈。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本例反驳的是「连通且最小度至少 2 就足够」，没有声称「无桥就是充分条件」。遍历实现与队列/栈仍回 \"},{\"t\":\"link\",\"v\":\"DSA\",\"href\":\"../../cs-basics/06-data-structures-algorithms/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例三：从「走不下去」到拼接回路\",\"id\":\"h-11\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"巡检图允许重边和自环。顶点 A、B、C、D、E，边按编号为 \"},{\"t\":\"code\",\"v\":\"0:AB, 1:BC, 2:CA, 3:CD, 4:DE, 5:EC, 6:EE\"},{\"t\":\"text\",\"v\":\"，其中 6 号是 E 上的自环。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"先查前提。\"}]},{\"t\":\"text\",\"v\":\" 度数为 A=2，B=2，C=4，D=2，E=4（E 来自 DE、EC 各 1，自环 2）。全为偶数；所有边都在同一个连通分量里，且没有孤立点需要额外说明。按欧拉回路定理，回路存在。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"贪心会在哪里停下。\"}]},{\"t\":\"text\",\"v\":\" 从 A 出发，每次走编号最小的未用边：A→B→C→A。此时 A 的两条边都已用完，走不下去，但 CD、DE、EC、EE 还没走。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"为什么停不住中途点。\"}]},{\"t\":\"text\",\"v\":\" 看当前这段迹正停在顶点 v、且 v 不是这段起点的那一刻。已用度数这样计：普通边每用一条加 1，自环整条加 2（本例 E 上的自环就是 2）。这段迹还没离开 v，所以经普通边进入的次数比离开的次数多 1；自环进出成对，只加偶数。已用度数因此是奇数。v 原来的度是偶数，剩余度数 = 偶数 − 奇数，仍是奇数，故至少为 1，还有未用边可走。这一步不能换成「每进入一次都离开一次」：那句话说的是已经配对完成的访问，而此刻最后一次进入还没有离开。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"起点可以停下，并且迹是闭合的。\"}]},{\"t\":\"text\",\"v\":\" 起点出发前已用度数为 0，是偶数。之后每离开一次再回到起点，普通边成对，自环仍只加 2，已用度数保持偶数，剩余度数也是偶数，可以变成 0。上面停在 A 时剩余正好是 0，所以停点是这段的起点，走出的是闭迹。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"严格化：拼接。\"}]},{\"t\":\"text\",\"v\":\" 已走出的闭迹 \"},{\"t\":\"code\",\"v\":\"A,B,C,A\"},{\"t\":\"text\",\"v\":\" 经过 C，而 C 还有未用边。从 C 再走一条只用未用边的闭迹：C→D→E→C；回到 C 后 E 还剩自环，再从 E 拼入 E→E。把小闭迹逐个嵌回大闭迹，得到\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"code\",\"v\":\"A, B, C, D, E, E, C, A\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"共 7 条边，每条恰好一次。这就是知识要点里拼接证明的具体执行：上面的奇偶计算说明，偶度时这段迹只会在自己的起点走不动，因此是闭迹；连通保证只要有边未用，就有未用边挂在已走出的点上。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"算法实现。\"}]},{\"t\":\"text\",\"v\":\" 下面的 C 程序用显式栈完成同一件事（Hierholzer 算法）：栈顶顶点若还有未用边就沿边前进，否则出栈并记入回路。栈的用法见 \"},{\"t\":\"link\",\"v\":\"数据结构与算法\",\"href\":\"../../cs-basics/06-data-structures-algorithms/\"},{\"t\":\"text\",\"v\":\" 的「线性结构」，栈的 C 实现练习见 \"},{\"t\":\"link\",\"v\":\"问题求解\",\"href\":\"../../programming-basics/05-problem-solving/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"code\",\"lang\":\"c\",\"code\":\"#include \\u003cstdio.h>\\n\\nenum { N = 5, M = 7 };\\nstatic const char name[N] = {'A', 'B', 'C', 'D', 'E'};\\nstatic const int from[M] = {0, 1, 2, 2, 3, 4, 4};\\nstatic const int to[M] = {1, 2, 0, 3, 4, 2, 4}; /* 最后一条是 E 的自环 */\\n\\nint main(void) {\\n    int deg[N] = {0};\\n    for (int e = 0; e \\u003c M; e++) {\\n        deg[from[e]]++;\\n        deg[to[e]]++; /* 自环在这里被加 2 */\\n    }\\n    for (int v = 0; v \\u003c N; v++) {\\n        if (deg[v] % 2 != 0) {\\n            printf(\\\"%c 是奇度顶点，没有欧拉回路\\\\n\\\", name[v]);\\n            return 1;\\n        }\\n    }\\n\\n    int used[M] = {0}, next_edge[N] = {0};\\n    int stack[M + 1], circuit[M + 1], top = 0, len = 0;\\n    stack[top++] = from[0]; /* 从一个非零度顶点出发 */\\n    while (top > 0) {\\n        int v = stack[top - 1];\\n        while (next_edge[v] \\u003c M &&\\n               (used[next_edge[v]] ||\\n                (from[next_edge[v]] != v && to[next_edge[v]] != v))) {\\n            next_edge[v]++;\\n        }\\n        if (next_edge[v] == M) { /* v 已无未用边：出栈并记入回路 */\\n            circuit[len++] = v;\\n            top--;\\n        } else {\\n            int e = next_edge[v];\\n            used[e] = 1;\\n            stack[top++] = (from[e] == v) ? to[e] : from[e];\\n        }\\n    }\\n    if (len != M + 1) {\\n        printf(\\\"有边没有走到：非零度部分不连通\\\\n\\\");\\n        return 1;\\n    }\\n    for (int i = len - 1; i >= 0; i--) {\\n        printf(\\\"%c%s\\\", name[circuit[i]], i > 0 ? \\\" \\\" : \\\"\\\\n\\\");\\n    }\\n    return 0;\\n}\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"程序输出 \"},{\"t\":\"code\",\"v\":\"A B C D E E C A\"},{\"t\":\"text\",\"v\":\"。实现上的三个对应关系：\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"code\",\"v\":\"deg\"},{\"t\":\"text\",\"v\":\" 检查对应「全为偶数」这一必要条件；\"},{\"t\":\"code\",\"v\":\"len != M + 1\"},{\"t\":\"text\",\"v\":\" 检查对应连通性：若非零度部分分成两块，从起点出发只能用完自己那一块的边。\"}]},{\"inlines\":[{\"t\":\"code\",\"v\":\"used\"},{\"t\":\"text\",\"v\":\" 按边编号而不是按端点对标记，因此两条重边会被当作两条不同的边，自环也只会被使用一次。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"每个点的 \"},{\"t\":\"code\",\"v\":\"next_edge\"},{\"t\":\"text\",\"v\":\" 只前进不后退，但这里每次都扫描整张边表，总代价是 \"},{\"t\":\"code\",\"v\":\"O(n·m)\"},{\"t\":\"text\",\"v\":\"；改用邻接表（见 \"},{\"t\":\"link\",\"v\":\"数据结构与算法\",\"href\":\"../../cs-basics/06-data-structures-algorithms/\"},{\"t\":\"text\",\"v\":\" 的「图」）后可降到 \"},{\"t\":\"code\",\"v\":\"O(n+m)\"},{\"t\":\"text\",\"v\":\"。\"}]}]},{\"t\":\"h\",\"level\":3,\"text\":\"例四：遍边和遍点，四张图分开判\",\"id\":\"h-12\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"欧拉问题看度数和连通性；哈密顿问题要求每个\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"顶点\"}]},{\"t\":\"text\",\"v\":\"恰好一次，没有类似的度数判据。下面四张简单图逐一分开判断。\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"图\"}],[{\"t\":\"text\",\"v\":\"欧拉回路\"}],[{\"t\":\"text\",\"v\":\"欧拉迹\"}],[{\"t\":\"text\",\"v\":\"哈密顿圈\"}],[{\"t\":\"text\",\"v\":\"哈密顿路\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"蝶形图：三角形 ABC 与 CDE 共用 C\"}],[{\"t\":\"text\",\"v\":\"有\"}],[{\"t\":\"text\",\"v\":\"有\"}],[{\"t\":\"text\",\"v\":\"无\"}],[{\"t\":\"text\",\"v\":\"有，如 A,B,C,D,E\"}]],[[{\"t\":\"text\",\"v\":\"完全图 K₄\"}],[{\"t\":\"text\",\"v\":\"无，4 个奇度点\"}],[{\"t\":\"text\",\"v\":\"无\"}],[{\"t\":\"text\",\"v\":\"有\"}],[{\"t\":\"text\",\"v\":\"有\"}]],[[{\"t\":\"text\",\"v\":\"3×3 网格（9 点 12 边）\"}],[{\"t\":\"text\",\"v\":\"无，4 个奇度点\"}],[{\"t\":\"text\",\"v\":\"无\"}],[{\"t\":\"text\",\"v\":\"无\"}],[{\"t\":\"text\",\"v\":\"有，蛇形走法\"}]],[[{\"t\":\"text\",\"v\":\"5 个点的圈 C₅\"}],[{\"t\":\"text\",\"v\":\"有\"}],[{\"t\":\"text\",\"v\":\"有\"}],[{\"t\":\"text\",\"v\":\"有\"}],[{\"t\":\"text\",\"v\":\"有\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"蝶形图和网格的「无哈密顿圈」需要证明，这里用一个自写的引理：\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"引理\"}]},{\"t\":\"text\",\"v\":\"：若图 G 有哈密顿圈，则从 G 中删去任意 k 个顶点（1 ≤ k \\u003c n）后，剩下的图至多有 k 个连通分量。圈至少 3 个顶点，所以 n≥3 就够；n≥4 是上面二部图那条界，不是这条引理的假设。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"先只看哈密顿圈本身。圈上删去 k 个点，剩下的顶点沿圈被切成若干段连续的路；每两段之间至少夹着一个被删的点，所以段数至多为 k。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"每一段内部仍然连通，所以只看圈的边时，剩余部分至多 k 个连通分量。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"G 的其余边只会把段连起来，不会把一段拆开，所以 G 删点后的连通分量数也至多为 k。\"}],\"n\":3}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"蝶形图删去 C 后剩 \"},{\"t\":\"code\",\"v\":\"{A,B}\"},{\"t\":\"text\",\"v\":\" 和 \"},{\"t\":\"code\",\"v\":\"{D,E}\"},{\"t\":\"text\",\"v\":\" 两块，k=1 却有 2 个分量，所以没有哈密顿圈；可它的全部顶点都是偶度且连通，欧拉回路存在。K₄ 正好相反。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"3×3 网格用另一种障碍：按国际象棋棋盘交替染色，每条边连接异色两点，深色 5 个、浅色 4 个。哈密顿圈必须深浅交替，两色数量应相等，矛盾。这是二部图的计数论证，二部图本身见 \"},{\"t\":\"link\",\"v\":\"二分图与匹配\",\"href\":\"../08-bipartite-matching/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"同一引理换成路的版本是「至多 k+1 个分量」（路被删 k 个点后至多 k+1 段）。注意引理只是必要条件：满足它的图仍可能没有哈密顿圈，判定一般图的哈密顿圈是 NP 完全问题，见 \"},{\"t\":\"link\",\"v\":\"复杂度与归约\",\"href\":\"../14-complexity-reductions/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-13\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能标明一条序列是游走、迹、简单路还是圈。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能写全欧拉条件，特别是不漏连通性。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能用桥或孤立点构造不可能性证明。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能在多重图、有向图中检查欧拉条件，并说明自环与零度顶点如何处理。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能用删点后的连通分量数证明一张图没有哈密顿圈，且不把它与欧拉条件混用。\"}]}]},{\"t\":\"h\",\"level\":3,\"text\":\"分层练习\",\"id\":\"h-14\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"【入门】机房线路图：顶点 P、Q、R、T，边为 P–Q 两条（重边）、Q–R、R–P、R 上一条自环，T 是尚未接线的机柜。(a) 判断是否有欧拉回路、欧拉迹，若有给出一条。(b) 若把重边合并、删去自环，结论如何变化？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"【进阶】有向巡检。(a) 边为 \"},{\"t\":\"code\",\"v\":\"A→B, B→C, C→A, A→D, D→A\"},{\"t\":\"text\",\"v\":\"，是否存在每条边恰走一次、沿边方向的闭合巡检？给出路线。(b) 删去 \"},{\"t\":\"code\",\"v\":\"D→A\"},{\"t\":\"text\",\"v\":\" 后呢？(c) 边 \"},{\"t\":\"code\",\"v\":\"X→Y, Z→Y\"},{\"t\":\"text\",\"v\":\" 忽略方向时有欧拉迹，沿方向时有吗？写出有向图欧拉迹的完整条件。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"【进阶】两台核心交换机 H1、H2 各连接 5 台终端 L1 到 L5，终端之间、核心之间都不相连（即 K₂,₅）。(a) 是否有欧拉迹？(b) 是否有哈密顿圈？(c) 是否有哈密顿路？\"}],\"n\":3}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"(a) 度数为 P=3（两条重边加 RP），Q=3，R=4（QR、RP 各 1，自环 2），T=0。非零度部分连通，奇度点恰好 P、Q 两个，所以没有欧拉回路，有从 P 到 Q 的欧拉迹，如 \"},{\"t\":\"code\",\"v\":\"P, Q, P, R, R, Q\"},{\"t\":\"text\",\"v\":\"：依次用第一条 PQ、第二条 PQ、PR、自环、RQ，共 5 条边。T 度为 0，不影响结论；若要求「经过每个机柜」，那就是另一个问题。(b) 合并重边、删去自环后，顶点仍是 P、Q、R、T，T 没有被删掉，度仍为 0。非零度子图是三角形 PQR，只有这三点的度都是 2，不是整张图每个点度都是 2。非零度部分连通且这些度为偶数，所以有欧拉回路 \"},{\"t\":\"code\",\"v\":\"P, Q, R, P\"},{\"t\":\"text\",\"v\":\"，T 不在这条回路上。同一份记录换成简单图模型，结论从「只有迹」变成「有回路」，所以必须先写明模型。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"(a) 入度、出度：A 出 2 入 2，B、C、D 各出 1 入 1；忽略方向连通。全部相等，故有有向欧拉回路，如 \"},{\"t\":\"code\",\"v\":\"A, B, C, A, D, A\"},{\"t\":\"text\",\"v\":\"。(b) 删去后 A 出 2 入 1，D 出 0 入 1，其余平衡，有从 A 到 D 的有向欧拉迹 \"},{\"t\":\"code\",\"v\":\"A, B, C, A, D\"},{\"t\":\"text\",\"v\":\"，没有回路。(c) 没有：Y 入度 2、出度 0，任何有向迹最多从 Y 离开 0 次，却要进入 Y 两次，只能在终点进入一次。有向欧拉回路的条件是：每点入度等于出度，且所有非零度顶点在忽略方向后连通（在入出度相等时，这等价于它们同属一个强连通分量）。有向欧拉迹（起点终点不同）的条件是：起点出度比入度多 1，终点入度比出度多 1，其余点平衡，连通性要求同上。证明可补一条从终点指向起点的边，化归为回路情形。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"(a) H1、H2 度为 5，各 L 度为 2，图连通，奇度点恰好两个，有从 H1 到 H2 的欧拉迹，如 \"},{\"t\":\"code\",\"v\":\"H1, L1, H2, L2, H1, L3, H2, L4, H1, L5, H2\"},{\"t\":\"text\",\"v\":\"，共 10 条边。(b) 没有：删去 H1、H2（k=2）后剩 5 个孤立的终端，5 > 2，违反例四引理。(c) 也没有：路的版本要求删 2 个点后至多 3 个分量，而这里有 5 个。直观上，哈密顿路必须让终端和核心交替出现，7 个点中终端占 5 个，两台核心不够把它们隔开。这道题有欧拉迹却连哈密顿路都没有，正好说明两类问题不能互相推出。\"}],\"n\":3}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-15\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"5 个顶点组成单个环，有欧拉回路吗？有哈密顿圈吗？两者理由相同吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"两个互不相连的 4 点环，每点度数都为偶数，是否有一个使用全部边的欧拉回路？\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"3 点链 A–B–C 有哪些奇度点？能否有欧拉迹、欧拉回路、哈密顿路、哈密顿圈？\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"证明任意含圈的无向图中，圈上的一条边不是桥。不要只画一个例子。\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"都有。沿环一周既把各边用一次，也把各点访问一次；欧拉的条件按度和边连通性，哈密顿则由这条遍点圈直接见证，不能把两类一般判定混为一谈。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"没有。一个游走不能跨越没有边相连的两个分量；偶度条件不够。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"A、C 为奇点。沿 A–B–C 是欧拉迹也是哈密顿路；不能有欧拉回路，也不能有哈密顿圈。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"设被删边为 uv。圈除 uv 之外仍含一条 u 到 v 的路；任何原来使用 uv 的游走都可把这一步换成该替代路，因此删边不破坏原先的可达关系，分量数不增加。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-16\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Walks, Paths, and Cycles\",\"href\":\"https://vertex.degree/beginning/walks.html\"},{\"t\":\"text\",\"v\":\" — 路、圈、连通与可达关系。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Euler Tours\",\"href\":\"https://vertex.degree/degrees/euler.html\"},{\"t\":\"text\",\"v\":\" — 欧拉条件与拼接构造；章末推论给出有向回路：除孤立点外弱连通，且每个顶点入度等于出度。本页接口巡检场景独立设计。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Hamilton Cycles\",\"href\":\"https://vertex.degree/hard/hamilton.html\"},{\"t\":\"text\",\"v\":\" — 遍点与遍边问题的差异，充分条件只作后续拓展。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"UC Davis：How to Prove a Problem Is NP-Complete\",\"href\":\"https://www.cs.ucdavis.edu/~bai/ECS122A/Notes/NPC3.pdf\"},{\"t\":\"text\",\"v\":\" — 无向哈密顿圈的 NP 完全分类，明确区别有向与无向版本。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"MIT Theory of Computation 讲义\",\"href\":\"https://ocw.mit.edu/courses/18-404j-theory-of-computation-fall-2020/pages/lecture-notes/\"},{\"t\":\"text\",\"v\":\" — NP 完全性的形式语境，本页只引用哈密顿圈判定的既知分类。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018 版 12.9 节欧拉回路定理与哈密顿圈对照，以及 Problem 10.7 有向图欧拉回路的分步证明习题。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Princeton Algorithms：Directed Graphs\",\"href\":\"https://algs4.cs.princeton.edu/42digraph/\"},{\"t\":\"text\",\"v\":\" — 有向欧拉回路习题：每个顶点入度等于出度，且非零度顶点属于同一个强连通分量。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Princeton Algorithms：Undirected Graphs\",\"href\":\"https://algs4.cs.princeton.edu/41graph/\"},{\"t\":\"text\",\"v\":\" — 允许自环与重边的邻接表图类型，可对照例三的边表实现。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：图的建模与度数\",\"href\":\"../05-graphs-degrees/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 理论基础\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：树与生成树\",\"href\":\"../07-trees-spanning/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"原创谜题：每个接口只巡检一次\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"游走、迹、路与圈\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"连通分量、桥与割点\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"欧拉迹与欧拉回路\"},{\"id\":\"h-7\",\"level\":3,\"text\":\"哈密顿问题换成了遍点\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"小例题\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例一：巡检路线与回路障碍\"},{\"id\":\"h-10\",\"level\":3,\"text\":\"例二：所有度都够也不保证哈密顿圈\"},{\"id\":\"h-11\",\"level\":3,\"text\":\"例三：从「走不下去」到拼接回路\"},{\"id\":\"h-12\",\"level\":3,\"text\":\"例四：遍边和遍点，四张图分开判\"},{\"id\":\"h-13\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-14\",\"level\":3,\"text\":\"分层练习\"},{\"id\":\"h-15\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-16\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/07-trees-spanning\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"理论基础\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 树与生成树\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"树是「连得起来，又没有冗余圈」的结构；生成树保留可达性，最小生成树再优化总边权。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"理论基础 · 第 07 章。旧笔记里的「计算机理论」仍指专题页\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"要先会 06 的简单路和圈，以及 05 的握手定理。03 的归纳在本页写出删叶子这一次，练习不必先做完\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开平衡搜索树、堆的实现、Prüfer 编码和矩阵树定理。章末任务和自测可以不做\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"原创谜题：连接四个构建节点\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"节点 A、B、C、D 间候选连线及费用为 \"},{\"t\":\"code\",\"v\":\"AB:2, AC:5, AD:8, BC:3, BD:6, CD:1\"},{\"t\":\"text\",\"v\":\"。希望所有节点互相可达，并选出一棵总费用最小的树。为什么不能只给每个节点挑一条最便宜的线，就宣布解决？先理解「树」到底要求什么。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"树的几种等价刻画\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"对 \"},{\"t\":\"code\",\"v\":\"n≥1\"},{\"t\":\"text\",\"v\":\" 的有限简单无向图，下列条件等价：\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"连通且没有圈，即树的定义。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"任意两点之间恰有一条简单路。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"连通且边数为 n−1。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"无圈且边数为 n−1。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"两条不同的简单路会产生一个圈，故连通无圈推出唯一简单路；反向则由路的存在得到连通，由圈会给出两条路排除圈。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"为什么边数是 n−1？\"}]},{\"t\":\"text\",\"v\":\" 当 n 至少为 2，取一条最长简单路，其端点不能有路外邻点，否则可延长；也不能有除路上相邻点外的路内邻点，否则有圈。因此两端都是叶子。删去一个叶子及其唯一关联边，剩余图仍连通无圈；以 n 归纳，从单点 0 条边，得到 n 点 n−1 条边。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"连通图如果有圈，删去圈上一边仍连通，反复删至树，故连通图至少有 n−1 条边。于是「连通且 n−1 边」不能再有圈；「无圈且 n−1 边」则由每个树分量的边数求和可知只有一个分量。完整论证用到了前提，不能只凭边数猜。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"在树上把原来没有的一条边加回去，两端之间原有唯一简单路，于是恰好出现一个圈。若还有第二个新圈，去掉这条新边后会剩下两条不同的旧路。通关自测第 2 题用的就是这件事，证明已经写在这里。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"n≥2 的树还满足 \"},{\"t\":\"code\",\"v\":\"叶子数 = 2 + Σ(deg(v)−2)\"},{\"t\":\"text\",\"v\":\"，求和只对度至少为 3 的顶点。握手定理给出 \"},{\"t\":\"code\",\"v\":\"Σ deg(v) = 2n−2\"},{\"t\":\"text\",\"v\":\"，所以全体 \"},{\"t\":\"code\",\"v\":\"deg(v)−2\"},{\"t\":\"text\",\"v\":\" 之和为 −2。叶子每个贡献 −1，度为 2 的点贡献 0，度至少为 3 的点贡献正数，移项即得。右边的求和非负，所以这样的树至少有两个叶子。单点树的度是 0，不在公式里。有圈或变成森林时，\"},{\"t\":\"code\",\"v\":\"2n−2\"},{\"t\":\"text\",\"v\":\" 不再成立，公式要改。例四写出移项，并给出圈和森林上的失效情形。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"森林、生成树与桥\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"森林是没有圈的无向图，各连通分量都是树；有 n 个点、c 个分量的森林恰有 \"},{\"t\":\"code\",\"v\":\"n−c\"},{\"t\":\"text\",\"v\":\" 条边，包括孤立点分量。一般图如果有圈，删掉圈上的边不会增加分量，所以 n 个点、c 个分量时边数至少是 \"},{\"t\":\"code\",\"v\":\"n−c\"},{\"t\":\"text\",\"v\":\"，可以更多。通关自测第 1 题比较的就是这两句话。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"生成树是包含原图全部顶点的树形子图。有限非空图有生成树当且仅当它连通；断开的图只能逐分量取生成森林。任何桥都必须出现在每棵生成树中，否则桥两侧无法相连。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"树本身不要求选根、二叉、有序，也不等于二叉搜索树；BST、堆的实现已经在 \"},{\"t\":\"link\",\"v\":\"DSA\",\"href\":\"../../cs-basics/06-data-structures-algorithms/\"},{\"t\":\"text\",\"v\":\" 中。本关只讨论连接结构。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"最小生成树与交换论证\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"给有限连通无向图的边附实数权重，在所有生成树中总权最小者叫 MST；边权可为负、零或正，和 Dijkstra 的非负限制无关。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"割性质\"}]},{\"t\":\"text\",\"v\":\"：把顶点分成两个非空部分，某条跨割边 e 是所有跨割边中权重最小者，则\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"存在\"}]},{\"t\":\"text\",\"v\":\"一棵 MST 包含 e。若它是严格唯一的最轻跨割边，则每棵 MST 都包含它。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"证明：取任意 MST T。若 e 不在 T 中，把 e 加进去会形成唯一一个圈；圈上还有另一条跨同一割的边 f。删 f 加 e 仍是生成树，而且 \"},{\"t\":\"code\",\"v\":\"w(e)≤w(f)\"},{\"t\":\"text\",\"v\":\"，因此新树仍最优；若严格小于，则原 T 不可能最优。相同权重时不能直接宣称所有 MST 都包含任意指定的最轻边。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Kruskal 按权重从小到大考虑边，只收下不会在已选森林中形成圈的边。收下一条连接两个分量的边时，它是跨某个当前分量割的一条最轻边；交换时替换掉的边不在已选森林中，所以能保持「已有选择属于某棵 MST」的不变式。最终选满 n−1 条边即得到 MST。这里说明正确性，不重复并查集实现。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"每棵生成树都有 n−1 条边。把所有边权加上同一个常数 c，c 可以为负，每棵生成树的总权都增加 \"},{\"t\":\"code\",\"v\":\"(n−1)c\"},{\"t\":\"text\",\"v\":\"，谁更轻不变。\"},{\"t\":\"link\",\"v\":\"Minimum Spanning Trees\",\"href\":\"https://algs4.cs.princeton.edu/43mst/\"},{\"t\":\"text\",\"v\":\" 的练习用「比较结果不变」说明加上正常数不影响 Kruskal；边数相同则负数常数也只是平移总权。最短路不是这样，因为两条路的边数可以不同。分层练习第 3 题用一个三角形数这个差别。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"在允许自环的模型里，自环是圈，任何生成树都不含它。权再小，Kruskal 也会因为两端已经在同一点而跳过。负权不改变这件事。例三把自环、重边和并列权放在同一次执行里。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题\",\"id\":\"h-7\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：手算并给出最优理由\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"按权重考虑：先选 CD 的 1，再选 AB 的 2，再选 BC 的 3，形成 \"},{\"t\":\"code\",\"v\":\"A–B–C–D\"},{\"t\":\"text\",\"v\":\"，总费用为 6。前三条都连接不同分量，各自符合安全选择；得到生成树后停止。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"只说「我画了一棵费用为 6 的树」只能证明最优值不大于 6；交换论证和安全选择才说明不可能有更便宜的树。本例权重互异，因此还可进一步证明 MST 唯一，但唯一性不是求出一棵最优树的必要步骤。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：边数与最短路的两个陷阱\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一个 3 点圈再加一个孤立点，共 4 点、3 边，却不是树，说明 n−1 边不是单独充分条件。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"再看 \"},{\"t\":\"code\",\"v\":\"AB:2, BC:2, AC:3\"},{\"t\":\"text\",\"v\":\"：MST 选 AB、BC，总权 4；但从 A 到 C 的最短路是直接走费用 3 的 AC。MST 优化总网络费用，不保证每一对点之间走得最短。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例三：并列权重、重边与自环下的 Kruskal\",\"id\":\"h-10\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"五个构建节点 A 到 E 的候选链路如下（无向，带权，允许重边和自环）：\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"边\"}],[{\"t\":\"text\",\"v\":\"权\"}],[{\"t\":\"text\",\"v\":\"说明\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"B–B\"}],[{\"t\":\"text\",\"v\":\"−1\"}],[{\"t\":\"text\",\"v\":\"自环，负权\"}]],[[{\"t\":\"text\",\"v\":\"A–B\"}],[{\"t\":\"text\",\"v\":\"1\"}],[]],[[{\"t\":\"text\",\"v\":\"D–E\"}],[{\"t\":\"text\",\"v\":\"1\"}],[{\"t\":\"text\",\"v\":\"第一条\"}]],[[{\"t\":\"text\",\"v\":\"D–E\"}],[{\"t\":\"text\",\"v\":\"1\"}],[{\"t\":\"text\",\"v\":\"第二条，与上一条构成重边\"}]],[[{\"t\":\"text\",\"v\":\"A–C、B–C\"}],[{\"t\":\"text\",\"v\":\"2、2\"}],[{\"t\":\"text\",\"v\":\"并列\"}]],[[{\"t\":\"text\",\"v\":\"C–D、C–E\"}],[{\"t\":\"text\",\"v\":\"3、3\"}],[{\"t\":\"text\",\"v\":\"并列\"}]],[[{\"t\":\"text\",\"v\":\"B–D\"}],[{\"t\":\"text\",\"v\":\"4\"}],[]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"先查前提。\"}]},{\"t\":\"text\",\"v\":\" 图连通，所以生成树存在；若不连通，任何算法最多得到「最小生成森林」，每个分量各一棵。负权不影响：Kruskal 和 Prim 只比较权的大小，从不要求权为正。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"Kruskal 逐步执行。\"}]},{\"t\":\"text\",\"v\":\" 按权从小到大考察，端点已在同一分量就跳过：\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"B–B（−1）：两端同为 B，加入会成圈（自环是长度 1 的圈），跳过。负权自环再便宜也不可能出现在任何生成树里。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"A–B（1）：加入，分量 \"},{\"t\":\"code\",\"v\":\"{A,B}\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"第一条 D–E（1）：加入，分量 \"},{\"t\":\"code\",\"v\":\"{D,E}\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"第二条 D–E（1）：D、E 已连通，跳过。\"}],\"n\":4},{\"inlines\":[{\"t\":\"text\",\"v\":\"A–C（2）：加入，分量 \"},{\"t\":\"code\",\"v\":\"{A,B,C}\"},{\"t\":\"text\",\"v\":\"；随后 B–C（2）两端已连通，跳过。\"}],\"n\":5},{\"inlines\":[{\"t\":\"text\",\"v\":\"C–D（3）：加入，五点连通，共 4 条边，停止。总权 1+1+2+3=7。\"}],\"n\":6}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"并列意味着什么。\"}]},{\"t\":\"text\",\"v\":\" 若排序时把并列边换个顺序，Kruskal 会选第二条 D–E、B–C 或 C–E，总权仍是 7。三处并列各有 2 种选择，最小生成树恰好有 2×2×2=8 棵，权都等于 7。看割 \"},{\"t\":\"code\",\"v\":\"{A,B}\"},{\"t\":\"text\",\"v\":\" 对 \"},{\"t\":\"code\",\"v\":\"{C,D,E}\"},{\"t\":\"text\",\"v\":\"：横跨边是 A–C、B–C、B–D，最小权 2 由两条边并列。此时能保证的只是「每条并列最小边都\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"至少属于某棵\"}]},{\"t\":\"text\",\"v\":\" MST」，不能说「属于\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"每棵\"}]},{\"t\":\"text\",\"v\":\" MST」；后者要求横跨边中的最小者唯一。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"圈的交换论证：B–D 不在任何 MST 中。\"}]},{\"t\":\"text\",\"v\":\" 圈 \"},{\"t\":\"code\",\"v\":\"B–C–D–B\"},{\"t\":\"text\",\"v\":\" 的三条边权为 2、3、4，B–D 是唯一的最大者。\"}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"设某棵生成树 T 含 B–D。删去 B–D，T 恰好分成两块，B 和 D 分属两侧。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"圈上除 B–D 以外的部分是一条从 B 到 D 的路 B–C–D，它必有一条边 f 横跨这两块。\"}],\"n\":2},{\"inlines\":[{\"t\":\"code\",\"v\":\"T − (B–D) + f\"},{\"t\":\"text\",\"v\":\" 重新连通且仍有 n−1 条边，是生成树；因为 f 的权严格小于 4，新树更轻。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"所以含 B–D 的生成树都不是最小的。\"}],\"n\":4}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这里「严格最大」不能省：若圈上有并列最大边，交换后权不变，只能得出「存在一棵不含它的 MST」。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"与实现的对应。\"}]},{\"t\":\"text\",\"v\":\" Kruskal 需要排序（\"},{\"t\":\"link\",\"v\":\"数据结构与算法\",\"href\":\"../../cs-basics/06-data-structures-algorithms/\"},{\"t\":\"text\",\"v\":\" 的「查找与排序」）和「两点是否已连通」的判断：入门时可以每次用 DFS 或 BFS 检查（同一文档的「图」小节），代价较高；更快的并查集不在现有基础章节中，可作为后续拓展。Prim 每次从堆中取出最轻的横跨边，堆见同一文档的「树与堆」。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例四：叶子个数由高度数顶点决定\",\"id\":\"h-11\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"命题\"}]},{\"t\":\"text\",\"v\":\"：至少有 2 个顶点的树中，\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"code\",\"v\":\"叶子数 = 2 + Σ(deg(v) − 2)\"},{\"t\":\"text\",\"v\":\"，求和只对度数至少为 3 的顶点进行。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"直觉。\"}]},{\"t\":\"text\",\"v\":\" 一条路有 2 个叶子；每多一个度为 3 的分叉点，就多出一根「枝」，多一个末端。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"严格证明。\"}]}]},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"树有 n−1 条边，由握手定理 \"},{\"t\":\"code\",\"v\":\"Σ deg(v) = 2n − 2\"},{\"t\":\"text\",\"v\":\"，即 \"},{\"t\":\"code\",\"v\":\"Σ (deg(v) − 2) = −2\"},{\"t\":\"text\",\"v\":\"，对全部顶点求和。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"n ≥ 2 的树连通，没有度为 0 的点；按度数分类：叶子每个贡献 −1，度为 2 的点贡献 0，度至少为 3 的点贡献 \"},{\"t\":\"code\",\"v\":\"deg(v) − 2 > 0\"},{\"t\":\"text\",\"v\":\"。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"于是 \"},{\"t\":\"code\",\"v\":\"−(叶子数) + Σ_{deg≥3}(deg(v) − 2) = −2\"},{\"t\":\"text\",\"v\":\"，移项即得。\"}],\"n\":3}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"数值检验。\"}]},{\"t\":\"text\",\"v\":\" 一棵树有一个度为 4 的中心 H，两个度为 3 的节点 X、Y，其余度不超过 2：叶子数为 2+2+1+1=6。构造：H 连 X、Y 和两片叶子，X、Y 各连两片叶子，共 9 点 8 边；在 H 与 X 之间插入一个度为 2 的中继点，变成 10 点，叶子数仍为 6，因为度为 2 的点贡献 0。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"前提失效时。\"}]}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"有圈：圈 \"},{\"t\":\"code\",\"v\":\"C₅\"},{\"t\":\"text\",\"v\":\" 每点度为 2，公式给出 2 个叶子，实际为 0；第 1 步的 \"},{\"t\":\"code\",\"v\":\"2n − 2\"},{\"t\":\"text\",\"v\":\" 不成立。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"森林：c 棵树（都至少 2 个点）时度和为 \"},{\"t\":\"code\",\"v\":\"2(n − c)\"},{\"t\":\"text\",\"v\":\"，公式变为 \"},{\"t\":\"code\",\"v\":\"叶子数 = 2c + Σ_{deg≥3}(deg(v) − 2)\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"单点树：唯一顶点度为 0，既不是叶子也不满足第 2 步的分类，所以命题要求 n ≥ 2。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这也给出了「至少两个叶子」的另一种证明：右边的求和非负。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-12\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能用最长路端点或度数证明至少有 2 个顶点的树至少有两个叶子。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能完整使用树的等价条件，不漏连通或无圈前提。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能解释 MST 的交换证明及相等权重的边界。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能在有并列权、重边、自环、负权或不连通时说明 MST 是否存在、是否唯一。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能用度数和推出树的叶子个数，并指出公式对森林和有圈图如何失效。\"}]}]},{\"t\":\"h\",\"level\":3,\"text\":\"分层练习\",\"id\":\"h-13\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"【入门】一棵 10 个顶点的树里，有 1 个点度为 4，2 个点度为 3，其余点度都不超过 2。叶子有几个？度为 2 的点有几个？画出一种可能的树。若改为 10 个顶点、2 个连通分量、没有孤立点的森林，同样的度数要求还能满足吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"【进阶】四个节点的环形线路 A–B、B–C、C–D 权都为 1，D–A 权为 5，另有对角线 A–C 权为 5。图中有并列权，最小生成树是否唯一？由此判断：「边权互不相同」是 MST 唯一的充分条件、必要条件，还是充要条件？\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"【进阶】判断并说明理由：(a) 把每条边的权都加上同一个常数 c（c 可以为负），MST 的集合不变；对最短路也成立吗？(b) 给某点加一条权为 −10 的自环，可以降低 MST 的总权。(c) 图不连通时，Kruskal 无法输出任何有意义的结果。\"}],\"n\":3}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"由例四，叶子数为 \"},{\"t\":\"code\",\"v\":\"2 + (4−2) + (3−2) + (3−2) = 6\"},{\"t\":\"text\",\"v\":\"；度为 2 的点有 \"},{\"t\":\"code\",\"v\":\"10 − 1 − 2 − 6 = 1\"},{\"t\":\"text\",\"v\":\" 个。核对度和：\"},{\"t\":\"code\",\"v\":\"4 + 3 + 3 + 2 + 6×1 = 18 = 2×9\"},{\"t\":\"text\",\"v\":\"。一种构造：H（度 4）连 X、Y、L1、L2，X 连 L3、L4，Y 连 M 与 L5，M 连 L6，其中 M 是唯一度为 2 的点。森林不行：2 个分量时度和为 \"},{\"t\":\"code\",\"v\":\"2×(10−2) = 16\"},{\"t\":\"text\",\"v\":\"，高度数点已占 10，剩余 7 个点的度和只有 6，但没有孤立点意味着它们每个度至少为 1，度和至少 7，矛盾。用森林公式看也一样：叶子要 \"},{\"t\":\"code\",\"v\":\"4 + 2 + 1 + 1 = 8\"},{\"t\":\"text\",\"v\":\" 个，加上 3 个高度数点超过 10。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"唯一。任何生成树有 3 条边，每条权至少 1，总权为 3 当且仅当恰好选中 A–B、B–C、C–D，而它们构成一条路，是生成树；其他生成树都含一条权 5 的边，总权至少 7。所以唯一的 MST 是这三条权 1 的边，尽管图中权 1 与权 5 都有并列。结论：互不相同是充分条件（Princeton 讲义和 vertex.degree 第 9 章都在互异权假设下得出唯一性），但不是必要条件。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"(a) 对 MST 成立：连通图的每棵生成树都恰有 n−1 条边，总权统一变化 \"},{\"t\":\"code\",\"v\":\"(n−1)c\"},{\"t\":\"text\",\"v\":\"，大小顺序不变，所以 MST 集合不变；c 为负也一样。最短路不成立，因为不同路的边数不同：A–B、B–C 权 1，A–C 权 3 时，A 到 C 的最短路是 A–B–C（2 \\u003c 3）；全部加 2 后变为 6 与 5，最短路改为直连。最短路的证明见 \"},{\"t\":\"link\",\"v\":\"最短路与正确性证明\",\"href\":\"../11-shortest-path-proofs/\"},{\"t\":\"text\",\"v\":\"。(b) 错误。自环是长度 1 的圈，树不含圈，所以任何生成树都不含自环；Kruskal 处理它时两端已在同一分量，直接跳过。权再小也没有用。(c) 错误。图不连通时没有生成树，但 Kruskal 照常运行会对每个分量各得到一棵最小生成树，合起来是最小生成森林，边数为 n−c。需要改的是对结果的解读：不能把它称为 MST。\"}],\"n\":3}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-14\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"一片森林有 11 个顶点、4 个连通分量，边数是多少？若仅知道一般图这两个数，能断言同样的边数吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"对 n 顶点树加一条原来没有的边，为什么恰好形成一个圈？\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"一个三角形三条边权都为 1。每一条边都是某个割的最轻边，它是否必须在每棵 MST 中？\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"证明：连通图的一条桥必须出现在所有生成树中。\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"森林有 \"},{\"t\":\"code\",\"v\":\"11−4=7\"},{\"t\":\"text\",\"v\":\" 条边。一般图可能在某些分量含圈，所以至少为 7，但不一定恰为 7。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"原树中新增边的两端恰有一条简单路，加该边就构成一个圈。任何新圈必须使用新增边，因为旧图无圈；若存在另一个新圈，就会对应第二条旧简单路，与唯一性矛盾。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"不必须。任取两条边都是 MST，某条指定边可被省略；割性质在并列最轻时只保证某棵 MST 包含它。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"删除桥后，原图分成更多分量，桥两侧没有其他跨边。若生成树不含它，就不能连接两侧，与生成树连通矛盾。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-15\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Properties of Trees\",\"href\":\"https://vertex.degree/trees/properties.html\"},{\"t\":\"text\",\"v\":\" — 树、森林、叶子和归纳；本页构建节点费用例题为原创。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Trees and Spanning Trees\",\"href\":\"https://vertex.degree/trees/spanning.html\"},{\"t\":\"text\",\"v\":\" — 生成树、桥与最小代价的连接。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Princeton Algorithms：Minimum Spanning Trees\",\"href\":\"https://algs4.cs.princeton.edu/43mst/\"},{\"t\":\"text\",\"v\":\" — 割性质、交换论证、Prim 与 Kruskal。正文先假设边权互异，使 MST 唯一；另有练习说明各边权同加正常数不改变比较结果。本页单独处理并列权和负数常数。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Graph Theory 教材官网\",\"href\":\"https://diestel-graph-theory.com/\"},{\"t\":\"text\",\"v\":\" — 严格图论定义与证明的进一步参考。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018 版 12.11 节叶子引理、森林分量数与灰边引理；讲义注明并列权可以通过任意定序化归为互异权。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Princeton Algorithms：Undirected Graphs\",\"href\":\"https://algs4.cs.princeton.edu/41graph/\"},{\"t\":\"text\",\"v\":\" — 图的连通分量与 DFS、BFS 实现，可对照 Kruskal 中「是否已连通」的朴素判断。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：路径、连通与遍历\",\"href\":\"../06-walks-connectivity-euler/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 理论基础\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：二分图与匹配\",\"href\":\"../08-bipartite-matching/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"原创谜题：连接四个构建节点\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"树的几种等价刻画\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"森林、生成树与桥\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"最小生成树与交换论证\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"小例题\"},{\"id\":\"h-8\",\"level\":3,\"text\":\"例一：手算并给出最优理由\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例二：边数与最短路的两个陷阱\"},{\"id\":\"h-10\",\"level\":3,\"text\":\"例三：并列权重、重边与自环下的 Kruskal\"},{\"id\":\"h-11\",\"level\":3,\"text\":\"例四：叶子个数由高度数顶点决定\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-13\",\"level\":3,\"text\":\"分层练习\"},{\"id\":\"h-14\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-15\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/08-bipartite-matching\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 二分图与匹配\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"二分图把两类对象间的允许关系显出来；匹配问题既要找方案，也要能解释为什么某些方案必然不存在。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"计算机理论 · 第 08 关；基础主线的并行选修\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"02–03、05–07。\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开一般图花算法、Tutte 定理、网络流完整实现。\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"原创谜题：测试任务怎样分配\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"3 个测试任务 a、b、c 各需一个独占执行槽位，槽位为 1、2、3。允许集合为 \"},{\"t\":\"code\",\"v\":\"a:{1,2}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"b:{1}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"c:{2,3}\"},{\"t\":\"text\",\"v\":\"。每个任务只分一个槽位，每个槽位最多分一个任务。如果先给 a 分 1，是否意味着后面只能放弃 b？\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这不是排队时间优化，也不是概率分配。本关把每个槽位视为容量 1，只解决一对一的可行性。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"二分图与奇圈障碍\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若顶点可分成互不相交的 L、R，所有边都在两侧之间，则是二分图；同侧没有边。两侧数量不要求相等，图也不必连通。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"定理\"}]},{\"t\":\"text\",\"v\":\"：有限无向图是二分图，当且仅当没有奇长度圈。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一个方向：沿圈走，每次跨侧，回到起点必走偶数步。另一个方向：每个分量选根，按到根的最短路长度奇偶分两组；若一条边的两端同奇偶，取 BFS 树中从根到两端的路径，去掉共同前缀，再加这条边，就得到奇圈，矛盾。因此所有边必跨两组。每个分量都要处理，包括孤立点。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"匹配、极大与最大\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"匹配是两两没有共同端点的边集；被匹配边触及的顶点称为被覆盖。覆盖 L 全部顶点的匹配不一定覆盖 R；覆盖全部顶点才叫完美匹配。\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"极大匹配 maximal\"}]},{\"t\":\"text\",\"v\":\"：不能再直接添加一条边。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"最大匹配 maximum\"}]},{\"t\":\"text\",\"v\":\"：在所有匹配中边数最多。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"最大必极大，反过来不成立；局部无路可加不等于全局最优。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"增广路：撤销局部选择以换取更多\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"相对于匹配 M，交错路的边在「不属于 M」与「属于 M」之间交替。若起终点均未被 M 覆盖，而且第一、最后一条边都不在 M 中，就是增广路。把这条路上的匹配边去掉、非匹配边加进来，仍是匹配，边数恰好增加 1。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"引用 Berge 定理：匹配为最大，当且仅当不存在增广路。充分方向的关键是比较 M 与更大匹配 M′ 的对称差：每个顶点在其中度最多为 2，分量只能是交错路或交错圈；若 M′ 边数更多，必有一条路比 M 多一条边，它就是 M 的增广路。这解释为什么只找「还能直接加的边」不够。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"Hall 条件要检查整个子集\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"对二分图 \"},{\"t\":\"code\",\"v\":\"(L,R)\"},{\"t\":\"text\",\"v\":\"，记 \"},{\"t\":\"code\",\"v\":\"N(S)\"},{\"t\":\"text\",\"v\":\" 为 L 的子集 S 在 R 中所有可能邻点的集合。\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"Hall 定理\"}]},{\"t\":\"text\",\"v\":\"：存在覆盖 L 的匹配，当且仅当对每个 \"},{\"t\":\"code\",\"v\":\"S⊆L\"},{\"t\":\"text\",\"v\":\"，都有 \"},{\"t\":\"code\",\"v\":\"|N(S)|≥|S|\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"必要性由鸽巢原理得到：S 的各任务要用互不相同的槽位。充分性的证明梗概如下：取一个最大匹配，若有未覆盖的左点 u，从 u 沿非匹配边向右、匹配边向左搜索；记到达的左右点集为 S、T。没有增广路，所以 T 的每个点都有匹配对象，而且对象在 S 内。除 u 外，S 的每点都由匹配边到达，于是 \"},{\"t\":\"code\",\"v\":\"|S|=|T|+1\"},{\"t\":\"text\",\"v\":\"；所有 S 的邻点都被搜索到，故 \"},{\"t\":\"code\",\"v\":\"N(S)=T\"},{\"t\":\"text\",\"v\":\"，违反 Hall 条件。矛盾说明必须能覆盖 L。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"当 \"},{\"t\":\"code\",\"v\":\"|L|=|R|\"},{\"t\":\"text\",\"v\":\"，覆盖 L 就是完美匹配；若右侧更多，则可能留有空闲槽位。该定理不是让程序枚举全部 2^|L| 个子集的高效算法；具体求解可使用增广路。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题\",\"id\":\"h-8\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：沿增广路修复贪心\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"先选 a–1、c–3，此时 b 未配，槽位 2 未用。交错路是 \"},{\"t\":\"code\",\"v\":\"b–1–a–2\"},{\"t\":\"text\",\"v\":\"：b–1 不在 M 中，1–a 在，a–2 不在。翻转后变为 b–1、a–2，保留 c–3，得到全部 3 个任务的匹配。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"旧匹配已经极大，因为未配 b 只有槽位 1 可用，不能直接加；但它并非最大，因为我们构造了更大的方案。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：每个任务有候选仍可能失败\",\"id\":\"h-10\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"令 \"},{\"t\":\"code\",\"v\":\"a:{1}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"b:{1}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"c:{2,3}\"},{\"t\":\"text\",\"v\":\"。每个任务都有邻点，但 S 取 \"},{\"t\":\"code\",\"v\":\"{a,b}\"},{\"t\":\"text\",\"v\":\" 时，\"},{\"t\":\"code\",\"v\":\"N(S)={1}\"},{\"t\":\"text\",\"v\":\"，数量 1 小于 2；因此覆盖所有任务不可能。这是一个短的不可行证据，不必枚举所有匹配。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这类模型可帮助理解 Java/微服务的任务与实例配对，但真实服务还可能有容量、优先级与时间窗口；不能把容量多于 1 的实例直接当一个独占槽位。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-11\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能证明奇圈为什么阻碍二分划分。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能给出极大却非最大的匹配，并画出增广路。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能用一个明确的子集展示 Hall 障碍。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-12\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"一个有 7 个顶点的图，可能有完美匹配吗？为什么？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"在链 \"},{\"t\":\"code\",\"v\":\"u–1–v–2\"},{\"t\":\"text\",\"v\":\" 上，匹配只取中间边 1–v。它极大吗？最大吗？找出改进方案。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"左侧 \"},{\"t\":\"code\",\"v\":\"{a,b,c,d}\"},{\"t\":\"text\",\"v\":\" 的候选分别为 \"},{\"t\":\"code\",\"v\":\"{1,2}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"{1,2}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"{1,2}\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"{3,4}\"},{\"t\":\"text\",\"v\":\"。右侧总数与左侧相等，有完美匹配吗？\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"某图没有三角形，是否一定是二分图？给出最小的奇圈反例，并说明只检测三角形漏了什么。\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"不可能，每条匹配边覆盖 2 点，全部覆盖的顶点数必为偶数。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"极大：另外两条边都与中间边共端点，不能直接添加。非最大：改成 u–1、v–2，有 2 条边；整条链就是增广路。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"没有。取 S 为 \"},{\"t\":\"code\",\"v\":\"{a,b,c}\"},{\"t\":\"text\",\"v\":\"，只有 2 个共同候选槽位，违反 Hall。仅比较两侧总数不能排除局部瓶颈。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"不一定；5 点圈没有三角形，却是奇圈，不能二分。二分性排除的是所有奇圈，不只是长度 3。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-13\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Bipartite Graphs\",\"href\":\"https://vertex.degree/matchings/bipartite.html\"},{\"t\":\"text\",\"v\":\" — 二分图、奇圈与最大/极大区别；本页任务槽位实例为原创。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Kőnig’s Theorem\",\"href\":\"https://vertex.degree/matchings/konig.html\"},{\"t\":\"text\",\"v\":\" — 增广路及匹配算法；本页不展开最小顶点覆盖等价定理。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Hall’s Theorem\",\"href\":\"https://vertex.degree/matchings/hall.html\"},{\"t\":\"text\",\"v\":\" — 覆盖指定一侧的精确充要条件与适用方式。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018 版第 12 章，二分图与匹配的独立教材参考。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：树与生成树\",\"href\":\"../07-trees-spanning/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：着色与平面图\",\"href\":\"../09-coloring-planarity/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"原创谜题：测试任务怎样分配\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"二分图与奇圈障碍\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"匹配、极大与最大\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"增广路：撤销局部选择以换取更多\"},{\"id\":\"h-7\",\"level\":3,\"text\":\"Hall 条件要检查整个子集\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"小例题\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例一：沿增广路修复贪心\"},{\"id\":\"h-10\",\"level\":3,\"text\":\"例二：每个任务有候选仍可能失败\"},{\"id\":\"h-11\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-13\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/09-coloring-planarity\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 着色与平面图\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一套合法着色只是上界；证明不能更少才得到最优值。平面图的计数工具同样依赖清楚的前提。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"计算机理论 · 第 09 关；基础主线的并行选修\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"03–05、07–08。\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开四色定理证明、平面性线性算法、图曲面嵌入。\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"原创谜题：冲突检查分几批\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"5 个测试模块沿环两两冲突，另有一个总控检查与这 5 个模块都冲突。相冲突的测试不能在同一批运行，至少需要几批？把模块当顶点、冲突当边，一种批次编号就是一种合法顶点着色。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"色数要用上下界夹住\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"合法顶点着色要求每条边两端颜色不同；允许不相邻的点同色。非空图所需最少颜色数叫色数 χ(G)。这里不是边着色，也不是把图画得好看。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一个 k 点团中任意两点都邻接，必须用至少 k 色，给出色数下界。任意构造出的 k 色方案只给出上界 \"},{\"t\":\"code\",\"v\":\"χ(G)≤k\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"逐点贪心着色时，每点最多有 Δ 个邻点，其中 Δ 是最大度，所以准备 Δ+1 种颜色总能找到未被已着色邻点使用的颜色；得到 \"},{\"t\":\"code\",\"v\":\"χ(G)≤Δ+1\"},{\"t\":\"text\",\"v\":\"。这个上界不一定紧，贪心也可能因顶点顺序不同而用更多颜色。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"平面图不是某一张画\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"平面图\"}]},{\"t\":\"text\",\"v\":\"是存在一种无交叉画法的图；选定的一种无交叉画法叫平面嵌入。允许边弯曲，交叉处若不是原图顶点，就不能临时「加个点」改变图。某张随手画有交叉，并不能证明图非平面。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"嵌入把平面分成面，最外部的无界区域也算一个面。对有限连通平面嵌入，若顶点、边、面数为 n、m、f，则\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"欧拉公式\"}]},{\"t\":\"text\",\"v\":\"是 \"},{\"t\":\"code\",\"v\":\"n−m+f=2\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"证明思路：树有 m=n−1，只有外部一个面，所以成立。若还有圈，删去圈上一条边会把它两侧的两个面合成一个，m、f 同减 1，且保持连通，式子不变；重复到树即可。非连通的推广为 \"},{\"t\":\"code\",\"v\":\"n−m+f=1+c\"},{\"t\":\"text\",\"v\":\"，c 是连通分量数，不能忘了修正常数。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"从面长推出边数限制\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"对 n 至少为 3 的简单平面图，有 \"},{\"t\":\"code\",\"v\":\"m≤3n−6\"},{\"t\":\"text\",\"v\":\"。先看连通情况：每个面边界长度至少为 3，按边界出现次数计数，每条边贡献两侧，故 \"},{\"t\":\"code\",\"v\":\"3f≤2m\"},{\"t\":\"text\",\"v\":\"；联立欧拉公式得到限制。桥的两侧可能属于同一面，但它在该面边界中计两次，并不是少计一侧。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若图还是二分图，则没有奇圈，面边界闭游走长度为偶数；在上述规模条件下至少为 4，得到 \"},{\"t\":\"code\",\"v\":\"4f≤2m\"},{\"t\":\"text\",\"v\":\"，从而 \"},{\"t\":\"code\",\"v\":\"m≤2n−4\"},{\"t\":\"text\",\"v\":\"。不连通时可在各分量间添加连接边而保持平面性；二分图可先交换某分量两侧颜色再连接，因此同样得到这两个边数上界。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这些都是平面性的\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"必要条件\"}]},{\"t\":\"text\",\"v\":\"，不是充分条件。通行的四色定理断言每个有限简单平面图都可用至多 4 色顶点着色；本关引用这个深结果，不提供其完整证明，也不能从欧拉公式几行就推出它。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题\",\"id\":\"h-7\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：冲突环加一个总控\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"5 点环不能用 2 色，因为沿奇圈交替着色会在首尾冲突；用 3 色可以，故色数恰为 3。总控与环上每点相邻，不能使用环上出现的任何颜色，至少再需一种颜色；给总控第 4 色即可。因此最少 4 批。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这个图可以画成中心一点加外侧 5 点环，是平面图。n=6，m=10，有 5 个内部三角面与 1 个外部面，\"},{\"t\":\"code\",\"v\":\"6−10+6=2\"},{\"t\":\"text\",\"v\":\"。平面不等于二分，也不等于只需 2 色。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：一个上界无法一键判定平面\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"K₅ 有 5 点、10 边，超过 \"},{\"t\":\"code\",\"v\":\"3×5−6=9\"},{\"t\":\"text\",\"v\":\"，所以非平面。K₃,₃ 有 6 点、9 边，并未超过一般限制 12，但它是二分图，超过二分限制 \"},{\"t\":\"code\",\"v\":\"2×6−4=8\"},{\"t\":\"text\",\"v\":\"，同样非平面。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这说明不能在通过一个必要条件之后就宣布可行。工程上的平面布线也可能要求固定端点、直线边或多层板；数学平面图模型只是其中一种理想化要求。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-10\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能给色数同时提供上界构造和下界论证。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能区分平面图、平面嵌入和面，正确计外部面。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能写全简单图、n≥3 等边数界前提。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-11\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"7 点环的色数是多少？分别给下界与上界。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"K₄ 可平面嵌入，求面数；它的色数是多少？这两问各用什么依据？\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"一个简单图有 8 个顶点、19 条边，可能是平面图吗？若只知道有 18 条边，就能保证平面吗？\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"为什么不能把「所有平面图至多 4 色」倒过来说「所有至多 4 色图都平面」？给出具体反例。\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"是 3。奇圈排除 2 色；先用两色交替给前 6 点着色，第 7 点用第 3 色，得到上界。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"n=4、m=6，欧拉公式得 f=4。K₄ 本身是 4 点团，所以至少 4 色；各点异色可行，故恰为 4。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"19 大于 \"},{\"t\":\"code\",\"v\":\"3×8−6=18\"},{\"t\":\"text\",\"v\":\"，不可能。18 只通过必要条件，仍不能保证平面。具体构造：先取 5 点完全图，再增加 x、y、z 三点，给它们分别连向原图中 3、2、3 个不同点；共 8 点、18 边，仍包含非平面的 K₅，所以不可能平面。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"K₃,₃ 是二分图，可用 2 色，却不是平面图。一个蕴含式一般不能反向使用。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-12\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Graph Coloring\",\"href\":\"https://vertex.degree/hard/coloring.html\"},{\"t\":\"text\",\"v\":\" — 贪心着色与色数上下界；本页总控冲突例题独立编写。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Planar Graphs\",\"href\":\"https://vertex.degree/planar/planar.html\"},{\"t\":\"text\",\"v\":\" — 平面嵌入、面与欧拉公式。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Planarity Testing\",\"href\":\"https://vertex.degree/planar/testing.html\"},{\"t\":\"text\",\"v\":\" — 简单平面图及二分平面图的边数界，强调不能反向使用。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Coloring Maps\",\"href\":\"https://vertex.degree/planar/coloring-maps.html\"},{\"t\":\"text\",\"v\":\" — 四色定理与地图模型，适合作为选读而非本关必证内容。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018 版第 13 章，平面图的独立证明参考。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：二分图与匹配\",\"href\":\"../08-bipartite-matching/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：有向图与依赖顺序\",\"href\":\"../10-digraphs-dag/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"原创谜题：冲突检查分几批\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"色数要用上下界夹住\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"平面图不是某一张画\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"从面长推出边数限制\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"小例题\"},{\"id\":\"h-8\",\"level\":3,\"text\":\"例一：冲突环加一个总控\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例二：一个上界无法一键判定平面\"},{\"id\":\"h-10\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-11\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/10-digraphs-dag\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 有向图与依赖顺序\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"方向让「能去」与「能回来」变成两件事；无环则把依赖问题变成可以逐步消去和递推的顺序问题。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"计算机理论 · 第 10 关；基础主线的并行选修\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"02–03、05–06；选读递推需 04。\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开分布式调度实现、动态拓扑排序、并行资源优化。\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"原创谜题：四步构建的先后顺序\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"步骤为 P「准备元数据」、G「生成代码」、T「测试」、D「打包」。要求 P 在 G、T 之前，G、T 都在 D 之前，得到边 \"},{\"t\":\"code\",\"v\":\"P→G, P→T, G→D, T→D\"},{\"t\":\"text\",\"v\":\"。G 与 T 谁先？能否只通过给步骤编号就解决一切调度问题？\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"有向图与强弱连通\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"有向边 \"},{\"t\":\"code\",\"v\":\"(u,v)\"},{\"t\":\"text\",\"v\":\" 与 \"},{\"t\":\"code\",\"v\":\"(v,u)\"},{\"t\":\"text\",\"v\":\" 不同。入度是指向某点的边数，出度是从某点出发的边数。每条有向边恰好贡献一次入度和一次出度，所以入度和、出度和都为 m，自环若存在也各计一次。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"有向游走必须顺边方向。有向图忽略方向后连通，叫弱连通；每一有序点对都能沿方向到达，叫强连通。\"},{\"t\":\"code\",\"v\":\"A→B\"},{\"t\":\"text\",\"v\":\" 弱连通，却不是强连通。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"用「相互可达」关系分出的等价类叫强连通分量；长度 0 的路保证每点至少和自己同类。把每个分量缩成一个点，并在原图存在\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"直接跨分量边\"}]},{\"t\":\"text\",\"v\":\"时加一条对应边、删除分量内部边，得到缩点图。缩点图必是 DAG：若不同分量之间存在有向圈，它们实际上相互可达，应合成同一分量，矛盾。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这里特意按直接跨分量边定义缩点图；有的材料选择用跨分量可达关系加边，那会多出传递边，但同样无环，不要在实现时混用。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"DAG 与拓扑序的等价关系\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"有向圈沿方向闭合，除首尾外不重复顶点。与简单无向图的圈不同，两个相反方向的边可形成长为 2 的有向圈；若模型允许自环，自环也算长为 1 的有向圈。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"DAG 是没有有向圈的有向图；其底层无向图可以有圈。拓扑序把全部顶点排成线性顺序，使每条边都由较早指向较晚。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"定理\"}]},{\"t\":\"text\",\"v\":\"：有限有向图有拓扑序，当且仅当它是 DAG。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若有拓扑序，沿边位置严格变大，不可能绕圈返回。反过来，非空有限 DAG 必有入度 0 的点：否则不断找前驱，有限顶点迫使重复，产生有向圈。取出一个入度 0 的点放在序列开头，剩余仍是 DAG，继续即可。空图有空拓扑序，但没有「至少一个源点」。用出度同理可得非空 DAG 至少有一个汇点。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"Kahn 算法：删源点为什么安全\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"维护剩余图的入度，把当前所有入度 0 的点加入待处理集合；每次取一个输出，删除它的所有出边，使新入度 0 的点也入队。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"不变式是：已输出的顺序不违反任何依赖；剩余入度只统计来自未输出点的边。每轮至少输出一个点，故有限次终止。如果还有点却没有入度 0 的点，就存在圈，无法输出完整拓扑序。邻接表加队列的实现时间为 \"},{\"t\":\"code\",\"v\":\"O(n+m)\"},{\"t\":\"text\",\"v\":\"，每点出队一次、每边处理一次。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"剩余点不一定全部在圈上；依赖圈的下游也会被阻塞。若要精确定位循环依赖，应进一步找强连通分量，而不是把剩余点统统指认为圈成员。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"拓扑递推与偏序\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"DAG 中允许长度 0 的可达关系是偏序：自反、传递；若两点不同却双向可达，会有有向圈，违反反对称。拓扑序是这个偏序的一种线性扩展，不必唯一。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"例如计算从起点 s 到各点的路径条数：令 ways(s)=1，其余为 0；按拓扑序，把每点的 ways 值加到各后继。等价地，非 s 顶点的路径数是各前驱路径数之和。有限 DAG 不会因循环产生无限多条游走；大图仍可能产生很大的计数，实现须注意整数范围。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题\",\"id\":\"h-8\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：两个合法顺序不是同一个计划\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"构建例子可取 \"},{\"t\":\"code\",\"v\":\"P,G,T,D\"},{\"t\":\"text\",\"v\":\" 或 \"},{\"t\":\"code\",\"v\":\"P,T,G,D\"},{\"t\":\"text\",\"v\":\"。从 P 到 D 有 \"},{\"t\":\"code\",\"v\":\"P→G→D\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"P→T→D\"},{\"t\":\"text\",\"v\":\" 共 2 条路径。但这两条路径不是「两种完整调度方案」的一般计数公式，只是在本例数字碰巧相同。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"拓扑序只满足先后约束；若 G 和 T 都要独占同一台机器，就不能同时做。最短工期、资源容量、公平性是额外优化条件，不能由「有拓扑序」自动解决。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：圈后的无辜下游\",\"id\":\"h-10\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"边为 \"},{\"t\":\"code\",\"v\":\"A→B, B→A, B→C, C→D\"},{\"t\":\"text\",\"v\":\"。四点入度都不为 0，Kahn 一开始就卡住。但真正的非平凡强连通分量只有 \"},{\"t\":\"code\",\"v\":\"{A,B}\"},{\"t\":\"text\",\"v\":\"；C、D 各自成分量，并不在圈上。缩点后是 \"},{\"t\":\"code\",\"v\":\"{A,B}→{C}→{D}\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这套语言能帮助阅读依赖系统，但 \"},{\"t\":\"link\",\"v\":\"Git 的提交/分支操作\",\"href\":\"../../cs-basics/04-git/\"},{\"t\":\"text\",\"v\":\" 与 \"},{\"t\":\"link\",\"v\":\"操作系统调度\",\"href\":\"../../cs-basics/02-operating-systems/\"},{\"t\":\"text\",\"v\":\" 仍有自己的规则；本关不把数学模型当成某个产品实现规范。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-11\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能分清弱连通、强连通与相互可达。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能证明非空有限 DAG 必有源点。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能逐轮计算剩余入度，并说明卡住说明了什么。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-12\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"边为 \"},{\"t\":\"code\",\"v\":\"A→B, A→C, B→D, C→D\"},{\"t\":\"text\",\"v\":\"。列出全部拓扑序；底层无向图是否有圈？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"在上述图加 \"},{\"t\":\"code\",\"v\":\"D→A\"},{\"t\":\"text\",\"v\":\"，还能拓扑排序吗？给出一个有向圈。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"为什么「有向图中总有源点」是错的？原定理必须补哪两个关键条件？\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"从 a 出发，边为 \"},{\"t\":\"code\",\"v\":\"a→b, a→c, b→c, b→d, c→d\"},{\"t\":\"text\",\"v\":\"，到 d 的有向路径数是多少？写出递推过程。\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"code\",\"v\":\"A,B,C,D\"},{\"t\":\"text\",\"v\":\" 与 \"},{\"t\":\"code\",\"v\":\"A,C,B,D\"},{\"t\":\"text\",\"v\":\"，只有两种。底层有无向圈 A–B–D–C–A，所以 DAG 不等于底层是森林。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"不能，例如 A→B→D→A 是有向圈。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"一个有向三角圈每点入度均为 1。定理要有限、无环，且保证存在源点时还需非空；无限单向前驱链也可没有源点。\"}],\"n\":3},{\"inlines\":[{\"t\":\"code\",\"v\":\"ways(a)=1\"},{\"t\":\"text\",\"v\":\"，\"},{\"t\":\"code\",\"v\":\"ways(b)=1\"},{\"t\":\"text\",\"v\":\"，\"},{\"t\":\"code\",\"v\":\"ways(c)=1+1=2\"},{\"t\":\"text\",\"v\":\"，\"},{\"t\":\"code\",\"v\":\"ways(d)=1+2=3\"},{\"t\":\"text\",\"v\":\"，对应 a–b–d、a–c–d、a–b–c–d。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-13\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Directed Acyclic Graphs\",\"href\":\"https://vertex.degree/trees/dags.html\"},{\"t\":\"text\",\"v\":\" — DAG、拓扑序、强连通与缩点；本页构建例题为原创，递推显式计入末尾一步。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Princeton Algorithms：Directed Graphs\",\"href\":\"https://algs4.cs.princeton.edu/42digraph/\"},{\"t\":\"text\",\"v\":\" — 有向图、环检测、强连通和拓扑排序的实现入口。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018 版第 10 章，DAG、依赖与偏序。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：着色与平面图\",\"href\":\"../09-coloring-planarity/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：最短路与算法证明\",\"href\":\"../11-shortest-path-proofs/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"原创谜题：四步构建的先后顺序\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"有向图与强弱连通\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"DAG 与拓扑序的等价关系\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"Kahn 算法：删源点为什么安全\"},{\"id\":\"h-7\",\"level\":3,\"text\":\"拓扑递推与偏序\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"小例题\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例一：两个合法顺序不是同一个计划\"},{\"id\":\"h-10\",\"level\":3,\"text\":\"例二：圈后的无辜下游\"},{\"id\":\"h-11\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-13\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/11-shortest-path-proofs\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 最短路与算法证明\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"会执行算法不等于知道它为什么正确。把已发现路径、最终距离与负圈的影响范围分开，才能选对最短路算法。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"计算机理论 · 第 11 关；基础主线的并行选修\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"03、05–07、10；DSA 的队列与堆。\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开重复写容器、全源最短路、A* 与 Johnson 算法。\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"原创谜题：直达不一定最快\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"静态有向通信图的边和延迟为 \"},{\"t\":\"code\",\"v\":\"s→a:6, s→b:2, b→a:1, a→t:2, b→t:8\"},{\"t\":\"text\",\"v\":\"。直达 a 的延迟是 6，但先去 b 再去 a 只需 3；到 t 的最佳路线是 s–b–a–t，费用为 5。只按边数分层或只挑某条最短边，都可能答错。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"距离与松弛的含义\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本关研究有限有向带权图上的单源最短游走费用；对于可达且不受相关负圈影响的目标，总能删掉非负圈得到不重复顶点的最短路。不可达的点记为正无穷。若 s 可到达某负圈，且该圈还能到达目标 t，就能绕圈任意多次，使到 t 的费用无下界，此时没有有限最短距离。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"算法的暂存标签 d(v) 表示已找到的某条 s 到 v 的路径或游走费用，所以它是最优距离的\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"上界\"}]},{\"t\":\"text\",\"v\":\"，不保证已经最优。松弛边 \"},{\"t\":\"code\",\"v\":\"u→v\"},{\"t\":\"text\",\"v\":\" 即尝试 \"},{\"t\":\"code\",\"v\":\"d(v)=min(d(v),d(u)+w(u,v))\"},{\"t\":\"text\",\"v\":\"，仅当 u 标签有限时进行。任何更新都能拼接出真实游走，因此不会凭空找到比所有合法游走更小的虚构答案。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"BFS：层号为什么最短\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"无权图或所有边权同为 1 时，用 FIFO 队列按距离层次处理。第一次发现邻点时立刻标记、设距离并入队，不等出队才标记。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"证明不变式是队列按已发现层号非递减排列，且第一次到达 v 的长度等于最少边数。若某点本可更早到达，其更短路径的前驱应在更早一层已被处理，便早已发现它，矛盾。邻接表下时间为 \"},{\"t\":\"code\",\"v\":\"O(n+m)\"},{\"t\":\"text\",\"v\":\"；邻接矩阵逐行扫描则通常是 \"},{\"t\":\"code\",\"v\":\"O(n²)\"},{\"t\":\"text\",\"v\":\"，不能不谈表示方式就报复杂度。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"Dijkstra：非负权在哪里起作用\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Dijkstra 反复选未确定点中标签最小的 u，确定其距离，再松弛其出边。这里说的是「确定后不再修改」的标准版本，要求边权非负。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"设已确定集合 S 的距离正确。看一条 s 到 u 的最短路，取它从 S 跨出的第一个点 y；前驱 x 已被正确确定并松弛过，故 y 的标签不大于这段最短路前缀费用。非负权保证前缀费用不大于整条路费用，所以 \"},{\"t\":\"code\",\"v\":\"d(u)≤d(y)≤dist(u)\"},{\"t\":\"text\",\"v\":\"；又因标签来自真实路径有 \"},{\"t\":\"code\",\"v\":\"d(u)≥dist(u)\"},{\"t\":\"text\",\"v\":\"，故恰好相等。源点先以 0 确定作为基例；只对有限可达标签继续处理。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"关键不是「每一步选了最小边」，而是选了\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"最小暂定总距离\"}]},{\"t\":\"text\",\"v\":\"。邻接表与支持减小键值的二叉堆实现可在 \"},{\"t\":\"code\",\"v\":\"O((n+m) log n)\"},{\"t\":\"text\",\"v\":\" 时间完成；朴素数组选择点则为 \"},{\"t\":\"code\",\"v\":\"O(n²+m)\"},{\"t\":\"text\",\"v\":\"，常写作稠密图下的 \"},{\"t\":\"code\",\"v\":\"O(n²)\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"DAG 与 Bellman–Ford\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"DAG 按拓扑序松弛即可：处理一个点时所有入边前驱都已处理，归纳可得距离正确；允许负权，因为不会绕圈。邻接表下时间 \"},{\"t\":\"code\",\"v\":\"O(n+m)\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"一般有向图允许负边时，可用 Bellman–Ford。为看清证明，采用\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"同步轮次\"}]},{\"t\":\"text\",\"v\":\"：本轮只从上一轮标签更新。令 dₖ(v) 为最多 k 条边的 s 到 v 游走的最小费用，初值 d₀(s)=0，其余无穷。每条最优游走要么不超过 k−1 条边，要么是前一条游走加最后一边，于是得到递推并证明第 k 轮标签的含义。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"没有源点可达负圈时，可删圈取得至多 n−1 边的最优简单路，所以 n−1 轮足够。再一轮若仍可改善，表明有源点可达负圈；其影响只传到从这些负圈可达的目标，并不让所有点答案都失效。逐边原地更新的常见实现也正确，但一轮可能传播多条边，不能声称它的标签「恰好等于最多本轮数条边的最优值」。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题与可运行验证\",\"id\":\"h-8\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：手算非负图\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"初始仅 s 为 0。确定 s 后，a 为 6、b 为 2；确定 b 后，a 改为 3、t 为 10；确定 a 后，t 改为 5；最后确定 t。这个顺序及证明依赖所有权重非负，并不模拟实际网络中不断变化的拥塞。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"下面是 Python 3 的同步 Bellman–Ford 教学版，额外存一份数组以保留轮次不变式；代码无第三方依赖。参数 edges 是可重复遍历的边三元组列表，权重使用整数；不处理浮点 NaN 或无穷权重。\"}]},{\"t\":\"code\",\"lang\":\"python\",\"code\":\"from math import inf\\n\\n\\ndef bellman_ford(n, edges, source):\\n    assert 0 \\u003c= source \\u003c n\\n    assert all(0 \\u003c= u \\u003c n and 0 \\u003c= v \\u003c n for u, v, _ in edges)\\n    dist = [inf] * n\\n    dist[source] = 0\\n    for _ in range(n - 1):\\n        nxt = dist.copy()\\n        for u, v, weight in edges:\\n            if dist[u] != inf:\\n                nxt[v] = min(nxt[v], dist[u] + weight)\\n        dist = nxt\\n    reachable_negative_cycle = any(\\n        dist[u] != inf and dist[v] > dist[u] + weight\\n        for u, v, weight in edges\\n    )\\n    return dist, reachable_negative_cycle\\n\\n\\nedges = [(0, 1, 6), (0, 2, 2), (2, 1, 1), (1, 3, 2), (2, 3, 8)]\\nassert bellman_ford(4, edges, 0) == ([0, 3, 2, 5], False)\\nassert bellman_ford(3, [(0, 1, 2), (1, 2, -4)], 0) == ([0, 2, -2], False)\\nassert bellman_ford(3, [(1, 2, -2), (2, 1, 1)], 0) == ([0, inf, inf], False)\\nassert bellman_ford(3, [(0, 1, 0), (1, 2, -2), (2, 1, 1)], 0)[1]\\nprint(\\\"shortest-path checks passed\\\")\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本程序返回负圈标志为真时，标签只代表有限轮次内的结果，\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"不能当作全部最终最短距离\"}]},{\"t\":\"text\",\"v\":\"；它没有继续标出每个受影响目标。时间为 \"},{\"t\":\"code\",\"v\":\"O(nm+n²)\"},{\"t\":\"text\",\"v\":\"（同步复制数组的代价也算入），额外空间 O(n)。这里按一次整数运算为常数计算，大整数的位运算成本另计。常见原地 Bellman–Ford 计入初始化和外层循环后为 \"},{\"t\":\"code\",\"v\":\"O(nm+n)\"},{\"t\":\"text\",\"v\":\" 时间，当 m≥1 时简写 \"},{\"t\":\"code\",\"v\":\"O(nm)\"},{\"t\":\"text\",\"v\":\"，额外空间 O(n)；本例不为简短忽略数组复制成本。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：负边击穿「确定就不改」\",\"id\":\"h-10\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"边为 \"},{\"t\":\"code\",\"v\":\"s→a:2, s→b:5, b→a:−4\"},{\"t\":\"text\",\"v\":\"。标准 Dijkstra 会先把 a 固定为 2，却漏掉 s–b–a 的费用 1，前面的非负前缀论证正是在这里失效。图没有圈，因此 DAG 方法和 Bellman–Ford 都可正确处理。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"若另有源点可达负圈，但从圈不能到达 a，不能据此宣称 a 也无有限答案；必须检查对目标的影响范围。容器实现、堆与遍历基础回 \"},{\"t\":\"link\",\"v\":\"DSA\",\"href\":\"../../cs-basics/06-data-structures-algorithms/\"},{\"t\":\"text\",\"v\":\"，证明模板回 \"},{\"t\":\"link\",\"v\":\"归纳与不变式\",\"href\":\"../03-proofs-induction/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-11\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能指出 BFS、Dijkstra、DAG 与 Bellman–Ford 各自前提。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能说明一个标签是上界还是已经证明的最优值。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能给出算法失败的反例，而不只是说「不适用」。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-12\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"所有边权都为 7，BFS 能否用于求最小费用？若边权有 1 和 7 两种呢？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"在例二加入 \"},{\"t\":\"code\",\"v\":\"a→t:3\"},{\"t\":\"text\",\"v\":\"，求 s 到 t 的最短费用；图中有负边就一定有负圈吗？\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"证明最短路的一个子段也必须最短，明确假设相关最短距离有限。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"n−1 轮以后还能改善，证明中为什么需要顶点数 n？返回负圈标志是否意味着每个目标都费用无下界？\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"相同正权时最少边数与最小费用等价，BFS 距离乘 7 即可。两种不同权重时不保证，边数少可能费用更大。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"走 s–b–a–t，费用 \"},{\"t\":\"code\",\"v\":\"5−4+3=4\"},{\"t\":\"text\",\"v\":\"。有负边不等于有负圈，本例仍是 DAG。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"若某子段可替换成更便宜的同端点游走，替换后得到更便宜的完整游走，违背最优。不存在相关负圈时可删掉非负圈得到不更贵的路，所以结论成立。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"至多 n−1 边覆盖所有简单路；超过该长度的游走会重复顶点，才需要借助圈来继续改善。负圈只影响源点能到达且从该圈还能到达的目标，不是全部目标。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-13\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"Princeton Algorithms：Shortest Paths\",\"href\":\"https://algs4.cs.princeton.edu/44sp/\"},{\"t\":\"text\",\"v\":\" — 松弛、Dijkstra、DAG、Bellman–Ford 与负圈的条件；本页图、数据和教学代码独立编写。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"MIT Introduction to Algorithms\",\"href\":\"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/\"},{\"t\":\"text\",\"v\":\" — BFS 与带权最短路的公开课程资料。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018 版第 6 章，正确性、不变式与终止性的通用证明框架。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Review of Proof-Writing\",\"href\":\"https://vertex.degree/appendix/proof-writing.html\"},{\"t\":\"text\",\"v\":\" — 以构造、上下界和算法终止组织证明的参考，不是本页最短路代码的来源。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：有向图与依赖顺序\",\"href\":\"../10-digraphs-dag/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：自动机与形式语言\",\"href\":\"../12-automata-languages/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"原创谜题：直达不一定最快\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"距离与松弛的含义\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"BFS：层号为什么最短\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"Dijkstra：非负权在哪里起作用\"},{\"id\":\"h-7\",\"level\":3,\"text\":\"DAG 与 Bellman–Ford\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"小例题与可运行验证\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例一：手算非负图\"},{\"id\":\"h-10\",\"level\":3,\"text\":\"例二：负边击穿「确定就不改」\"},{\"id\":\"h-11\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-13\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/12-automata-languages\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 自动机与形式语言\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"有限状态机只能记住有限种摘要，却足以识别许多格式；泵引理帮助证明有些格式超出了这个模型。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"计算机理论 · 第 12 关；基础主线的并行选修\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"01–03、05、10；C 示例可选。\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开上下文无关语言系统课、词法分析器工程、最小化算法。\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"原创谜题：流式标记检查器\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"输入是一串 0、1，只接受最后两个字符恰为 \"},{\"t\":\"code\",\"v\":\"10\"},{\"t\":\"text\",\"v\":\" 的串。输入可能很长，但不能把整串存起来。只记「末尾和目标前缀重合了多少」够不够？这就是用有限状态概括历史信息的例子。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"字符串、语言与 DFA\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"字母表 Σ 是有限符号集；Σ* 是全部有限字符串的集合，包括长度 0 的空串 ε。语言是 Σ* 的子集，不必是自然语言，也不必有限。空语言 \"},{\"t\":\"code\",\"v\":\"∅\"},{\"t\":\"text\",\"v\":\" 与只含空串的语言 \"},{\"t\":\"code\",\"v\":\"{ε}\"},{\"t\":\"text\",\"v\":\" 不同。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"确定有限自动机 DFA 可写成五元组 \"},{\"t\":\"code\",\"v\":\"(Q,Σ,δ,q₀,F)\"},{\"t\":\"text\",\"v\":\"：Q 是有限状态集，δ 为每个「状态、输入符号」指定唯一下一状态，q₀ 是初态，F 是接受状态集合。标准定义要求转移是全函数；不允许的符号或缺失转移，可按模型加入拒绝汇点。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"从初态逐个读取输入，全部读完后状态属于 F 才接受；中途经过接受状态不等于提前接受剩余任意输入。对空串不做转移，因此它被接受当且仅当初态属于 F。对长度做归纳，可以证明「当前状态记录的摘要」在每一步都正确。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"NFA 与正则表达式\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"NFA 允许某个状态在同一符号下有多个后继，也可有不消耗输入的 ε 转移。接受语义是\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"存在\"}]},{\"t\":\"text\",\"v\":\"一条分支完整读完输入并停在接受状态，而不是所有分支都成功，也不是随机挑一条。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"子集构造把「NFA 此刻所有可能状态的集合」当成 DFA 一个状态；含 ε 转移时还要取 ε 闭包。若 NFA 有 q 个状态，构造至多有 2^q 个状态，其中很多可能不可达。这说明 NFA 不比 DFA 多识别语言，只是表示可能更紧凑。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"理论正则表达式由符号、空语言、空串，通过并、连接、Kleene 星号构造；星号表示重复零次或更多次。Kleene 定理说 DFA、NFA 与这种正则表达式恰好描述同一类\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"正则语言\"}]},{\"t\":\"text\",\"v\":\"；本关引用其完整结果，不逐一证明所有转换。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"正则语言对并、交、补、连接与星号封闭。交可用状态对乘积构造；补则在转移完整的 DFA 上交换接受与非接受状态，并固定字母表。只对一个任意 NFA 直接翻转接受状态，通常不会得到补语言。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"泵引理的量词不能省略\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"有限状态数迫使足够长的接受运行重复状态：中间那一段输入可重复任意次。精确地说，若 L 正则，则存在整数 p≥1，使每个满足 \"},{\"t\":\"code\",\"v\":\"s∈L\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"|s|≥p\"},{\"t\":\"text\",\"v\":\" 的串，都\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"存在\"}]},{\"t\":\"text\",\"v\":\"分解 \"},{\"t\":\"code\",\"v\":\"s=xyz\"},{\"t\":\"text\",\"v\":\"，满足：\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"code\",\"v\":\"|xy|≤p\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"code\",\"v\":\"|y|≥1\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"对每个整数 i≥0，都有 \"},{\"t\":\"code\",\"v\":\"xyⁱz∈L\"},{\"t\":\"text\",\"v\":\"。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"用它证明非正则时：先让对方给任意 p，再选一个足够长的合法串；必须对\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"每一种允许的分解\"}]},{\"t\":\"text\",\"v\":\"，都能找出某个泵次数 i 使结果不在语言。不能自己挑一个坏分解，就宣布语言非正则。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"泵引理是正则的必要条件，不是判定正则性的充要条件；通过若干泵测试也不能证明正则。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题与 C 验证\",\"id\":\"h-7\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：三个状态足够\",\"id\":\"h-8\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"设状态 0 表示末尾既不是 \"},{\"t\":\"code\",\"v\":\"1\"},{\"t\":\"text\",\"v\":\" 也不是 \"},{\"t\":\"code\",\"v\":\"10\"},{\"t\":\"text\",\"v\":\"，状态 1 表示末尾为 \"},{\"t\":\"code\",\"v\":\"1\"},{\"t\":\"text\",\"v\":\"，状态 2 表示末尾为 \"},{\"t\":\"code\",\"v\":\"10\"},{\"t\":\"text\",\"v\":\"。状态 2 接受；这三个摘要互斥且覆盖全部二进制串。\"}]},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"当前状态\"}],[{\"t\":\"text\",\"v\":\"读入 0\"}],[{\"t\":\"text\",\"v\":\"读入 1\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"0\"}],[{\"t\":\"text\",\"v\":\"0\"}],[{\"t\":\"text\",\"v\":\"1\"}]],[[{\"t\":\"text\",\"v\":\"1\"}],[{\"t\":\"text\",\"v\":\"2\"}],[{\"t\":\"text\",\"v\":\"1\"}]],[[{\"t\":\"text\",\"v\":\"2\"}],[{\"t\":\"text\",\"v\":\"0\"}],[{\"t\":\"text\",\"v\":\"1\"}]]]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"例如 \"},{\"t\":\"code\",\"v\":\"110\"},{\"t\":\"text\",\"v\":\"：0→1→1→2，接受；\"},{\"t\":\"code\",\"v\":\"100\"},{\"t\":\"text\",\"v\":\"：0→1→2→0，拒绝。相应理论正则表达式可写为 \"},{\"t\":\"code\",\"v\":\"(0|1)*10\"},{\"t\":\"text\",\"v\":\"，没有必要记住整个前缀。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"下面完整程序只接受空字符结尾的 C 字符串，遇到非二进制字符直接拒绝；调用者须提供合法非空指针和可读取的字符串。保存为 \"},{\"t\":\"code\",\"v\":\"dfa.c\"},{\"t\":\"text\",\"v\":\"，用 \"},{\"t\":\"code\",\"v\":\"gcc -std=c17 -Wall -Wextra -Werror dfa.c -o dfa\"},{\"t\":\"text\",\"v\":\" 编译。\"}]},{\"t\":\"code\",\"lang\":\"c\",\"code\":\"#include \\u003cassert.h>\\n#include \\u003cstdbool.h>\\n#include \\u003cstdio.h>\\n\\nstatic bool ends_with_10(const char *text) {\\n    static const unsigned next[3][2] = {{0, 1}, {2, 1}, {0, 1}};\\n    unsigned state = 0;\\n    for (const char *p = text; *p != '\\\\0'; ++p) {\\n        if (*p != '0' && *p != '1') {\\n            return false;\\n        }\\n        unsigned bit = (unsigned)(*p - '0');\\n        state = next[state][bit];\\n    }\\n    return state == 2;\\n}\\n\\nint main(void) {\\n    assert(!ends_with_10(\\\"\\\"));\\n    assert(!ends_with_10(\\\"1\\\"));\\n    assert(ends_with_10(\\\"10\\\"));\\n    assert(ends_with_10(\\\"110\\\"));\\n    assert(!ends_with_10(\\\"100\\\"));\\n    assert(ends_with_10(\\\"1010\\\"));\\n    assert(!ends_with_10(\\\"102\\\"));\\n    puts(\\\"dfa checks passed\\\");\\n    return 0;\\n}\"},{\"t\":\"h\",\"level\":3,\"text\":\"例二：固定比例的分块标记不正则\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"令 \"},{\"t\":\"code\",\"v\":\"L={UⁿV²ⁿ : n≥0}\"},{\"t\":\"text\",\"v\":\"，U、V 是两个不同符号。假设 L 正则，取泵长度 p，选择 \"},{\"t\":\"code\",\"v\":\"s=UᵖV²ᵖ\"},{\"t\":\"text\",\"v\":\"。任意合法分解 s=xyz 都有 \"},{\"t\":\"code\",\"v\":\"|xy|≤p\"},{\"t\":\"text\",\"v\":\"，故非空 y 只包含 U。取 i=0 后，U 数减少而 V 数不变，不再满足 V 数恰为 U 数的 2 倍，所以不在 L，矛盾。这个论证覆盖所有允许分解，而不依赖我们挑中哪一段。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"它仍然可判定：使用无界计数器的普通算法可以数 U 和 V、检查顺序再比较二者的倍数关系。\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"非正则不等于不可计算\"}]},{\"t\":\"text\",\"v\":\"，只是有限状态模型不够。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"和 C、Java 的衔接\",\"id\":\"h-10\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"C 的逐字符扫描与 Java 的状态对象都可实现有限状态机，但引入无界容器或计数器后，整体模型不再只是固定状态数的 DFA。实际正则引擎可能带反向引用等扩展，不能把所有引擎功能都当成理论正则语言；性能还取决于实现策略。语言语法入门回 \"},{\"t\":\"link\",\"v\":\"C 核心概念\",\"href\":\"../../programming-basics/02-core-concepts/\"},{\"t\":\"text\",\"v\":\"，模型边界接 \"},{\"t\":\"link\",\"v\":\"可计算性\",\"href\":\"../13-computability/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-11\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能写清 DFA 的初态、完整转移与接受条件。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能解释 NFA 的存在分支语义和子集构造摘要。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能按正确量词顺序应用泵引理反证。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-12\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"上述 DFA 读入 \"},{\"t\":\"code\",\"v\":\"01010\"},{\"t\":\"text\",\"v\":\"、\"},{\"t\":\"code\",\"v\":\"101\"},{\"t\":\"text\",\"v\":\" 和 ε 后分别接受还是拒绝？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"一个 NFA 有一条完整读入后接受的分支，另有一条拒绝分支，整体是否接受？\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"为什么对 NFA 直接翻转接受状态，未必识别补语言？用「存在」与「所有」解释。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"有人选 \"},{\"t\":\"code\",\"v\":\"UᵖV²ᵖ\"},{\"t\":\"text\",\"v\":\"，只把第一个 U 当作 y 泵坏，便宣布证明完成。缺了什么？本页的完整证明怎样补上？\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"依次为接受、拒绝、拒绝；最终状态分别为 2、1、0。ε 保持初态，而初态非接受态。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"接受；NFA 只要求存在一条成功分支。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"原 NFA 拒绝意味着所有分支都不接受；翻转后得到的是存在一条分支原本不接受，二者量词不同。先确定化并补全转移，再翻转才是通用补构造。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"对方可能选择其他分解，只破坏我们挑的一种不足以否定存在性。本页说明任何 \"},{\"t\":\"code\",\"v\":\"|xy|≤p\"},{\"t\":\"text\",\"v\":\" 且 y 非空的分解，其 y 都只含 U，取 i=0 都会破坏二倍关系，因而覆盖所有分解。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-13\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"MIT Theory of Computation 讲义\",\"href\":\"https://ocw.mit.edu/courses/18-404j-theory-of-computation-fall-2020/pages/lecture-notes/\"},{\"t\":\"text\",\"v\":\" — Sipser 课程第 1–3 讲：DFA、NFA、正则转换与泵引理；免费讲义对应教材《Introduction to the Theory of Computation》第 1 章。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"MIT Lecture 3：Regular Pumping Lemma\",\"href\":\"https://ocw.mit.edu/courses/18-404j-theory-of-computation-fall-2020/resources/mit18_404f20_lec3-1/\"},{\"t\":\"text\",\"v\":\" — 泵引理的正式陈述和证明；本页流式尾缀识别器及代码为原创。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Java SE 25 Pattern 文档\",\"href\":\"https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/regex/Pattern.html\"},{\"t\":\"text\",\"v\":\" — 官方列出反向引用等实际引擎特性，用于区分工程正则与理论正则。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：目录\",\"href\":\"https://vertex.degree/contents.html\"},{\"t\":\"text\",\"v\":\" — 本专题借鉴其问题驱动方式；自动机与正则语言不属于该书正文覆盖范围。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：最短路与算法证明\",\"href\":\"../11-shortest-path-proofs/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：可计算性与停机问题\",\"href\":\"../13-computability/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"原创谜题：流式标记检查器\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"字符串、语言与 DFA\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"NFA 与正则表达式\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"泵引理的量词不能省略\"},{\"id\":\"h-7\",\"level\":2,\"text\":\"小例题与 C 验证\"},{\"id\":\"h-8\",\"level\":3,\"text\":\"例一：三个状态足够\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例二：固定比例的分块标记不正则\"},{\"id\":\"h-10\",\"level\":2,\"text\":\"和 C、Java 的衔接\"},{\"id\":\"h-11\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-13\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/13-computability\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 可计算性与停机问题\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"程序可能很慢，也可能永远不结束；可计算性研究的是是否存在总能给出正确答案的算法，而不是硬件够不够快。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"计算机理论 · 第 13 关；基础主线的并行选修\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"01–03、12。\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开递归论、Rice 定理证明、图灵度、可计算分析。\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"从一个不可能的万能检查器开始\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"设想工具 H 能读取任意程序 P 和输入 x，总在有限时间内准确回答「P 在 x 上会不会结束」。它比编译器警告、单元测试或运行超时强得多。这个工具并不存在；结论有严格的模型、量词与证明，不能简写成「所有程序都无法分析」。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"图灵机是模型，不是某台机器\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"标准图灵机由有限控制状态、读写头和可无界扩展的纸带组成；每步按当前状态与纸带符号读写、移动并转移。输入是有限串，某次运行用过的纸带部分在每个有限时刻仍是有限的，但没有预先固定的总内存上界。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"程序和输入可编码成字符串，通用图灵机可以模拟被编码的机器。多带机等常见变体在\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"可计算哪些函数\"}]},{\"t\":\"text\",\"v\":\"上与标准模型等价，运行效率则可能不同。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"Church–Turing 论题主张直觉上的有效机械计算都能由图灵机完成。它把非形式化概念与形式模型联系起来，是论题而不是在一个形式系统里直接证出的同类数学定理；特定形式模型之间的等价性则可以证明。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"现实计算机内存有限；停机不可判定的通用结论讨论的是允许无界内存和任意程序长度的算法模型。对固定有限状态系统，重复状态检查往往可以判定终止；不能把两种设定混在一起。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"可判定与可识别\",\"id\":\"h-5\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"把判定问题写成语言 L，即所有答案为「是」的编码集合。\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"L \"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"可判定\"}]},{\"t\":\"text\",\"v\":\"：存在算法，对每个输入都停止，并正确接受属于 L 的输入、拒绝不属于 L 的输入。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"L \"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"可识别\"}]},{\"t\":\"text\",\"v\":\"：存在算法，对属于 L 的输入终会接受；对不属于 L 的输入可以拒绝，也可以永不停止。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"每个可判定语言都可识别，反向不成立。如果 L 及其补语言都可识别，可交替模拟两个识别器，每个轮流走一步；恰好一个最终接受，所以可以判定 L。这里不能先把一个识别器运行到结束再启动另一个，否则第一个可能一直不结束。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"HALT 能识别，却不能总判定\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"定义 \"},{\"t\":\"code\",\"v\":\"HALT={⟨P,x⟩ : P 在输入 x 上最终停止}\"},{\"t\":\"text\",\"v\":\"，只讨论有效编码；无效编码可直接拒绝。识别它很简单：模拟 P(x)，如果停止就接受。如果不停止，模拟也会一直继续，因此这只是识别器。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"停机问题不可判定\"}]},{\"t\":\"text\",\"v\":\"的对角证明：假设存在总停机且正确的判定器 H。构造程序 D，输入是程序编码 p：若 H 判断 p 在自身编码 p 上停止，D 就永远循环；若 H 判断不会停止，D 就立刻停止。现在把 D 自己的编码 d 输入 D。\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"H 若说 D(d) 会停止，按 D 的定义它便不停止。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"H 若说不会停止，D(d) 反而停止。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"两种回答都错，因此假设的 H 不存在。构造 D 是因为程序可读入和模拟编码，不是依赖 C 函数指针的某种特殊技巧。证明只排除一个适用于\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"全部\"}]},{\"t\":\"text\",\"v\":\"程序和输入的万能判定器；许多具体程序仍可通过循环变式等方法证明终止。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"归约：把已知难题变成目标问题\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本关使用可计算多对一归约：若存在总可计算映射 f，使 \"},{\"t\":\"code\",\"v\":\"x∈A\"},{\"t\":\"text\",\"v\":\" 当且仅当 \"},{\"t\":\"code\",\"v\":\"f(x)∈B\"},{\"t\":\"text\",\"v\":\"，写作 \"},{\"t\":\"code\",\"v\":\"A≤ₘB\"},{\"t\":\"text\",\"v\":\"。那么若 B 可判定，就能先算 f 再运行 B 的判定器，从而判定 A。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"所以要证明 B 不可判定，应从一个已知不可判定的 A \"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"归约到 B\"}]},{\"t\":\"text\",\"v\":\"，而不是只做反方向。这里 f 只要求总可计算，不要求多项式时间；下一关的复杂度归约会加强效率条件。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题\",\"id\":\"h-8\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：超时记录不是反例证明\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"某程序运行 10 秒仍未结束，能推出它不终止吗？不能；它可能第 11 秒结束。设置运行预算是有用的工程保护，但它得到的是「预算内未完成」，不是关于无限未来的数学判定。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"相反，若一个固定整数计数器从 n 开始，每次在大于 0 时减 1，且 n 为给定非负整数，就可用严格下降的自然数证明它必终止。这与停机不可判定没有矛盾；见 \"},{\"t\":\"link\",\"v\":\"证明与归纳\",\"href\":\"../03-proofs-induction/\"},{\"t\":\"text\",\"v\":\"。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：把停机转成「是否触发完成标记」\",\"id\":\"h-10\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"设目标问题 B 问：某程序在给定输入上，是否曾执行到一个特别的完成标记指令。给定任意 HALT 实例 \"},{\"t\":\"code\",\"v\":\"⟨P,x⟩\"},{\"t\":\"text\",\"v\":\"，自动生成新程序 Q：先模拟 P(x)，模拟停止后才执行该标记。Q 的固定输入可设为空串。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"P(x) 停止，当且仅当 Q 会执行标记；生成 Q 的过程只是在代码外包一层模拟器，有限时间即可完成。如果有万能标记判定器，就能判定 HALT，因此 B 不可判定。这里使用的是模型内的特殊指令，不是去真实设备上执行操作；不需要真的让 Q 运行到结束才能生成 Q。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"和工程、AI 的衔接\",\"id\":\"h-11\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"静态分析器可在限定语言上精确分析，也可对更广输入保守近似或返回「未知」；停机定理不禁止这些工具。Java 程序、微服务调用或 AI Agent 的步骤预算可以提供运行边界，却不能让一个声称覆盖任意程序的检查器绕过对角论证。加入 AI 预测也不等于获得对所有输入都正确且总停机的证明。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-12\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能区分总停机判定器与只对肯定实例保证成功的识别器。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能逐步复述停机问题的自引用反证，不只背结论。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能写出不可判定归约的方向和两个实例答案的等价性。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-13\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"「某程序存在一个输入会停机」与「给定程序在给定输入上会停机」是不是同一句话？写出前者的量词。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"HALT 的模拟识别器在不属于 HALT 的输入上会发生什么？能否因此称它为判定器？\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"已知 A 不可判定且 \"},{\"t\":\"code\",\"v\":\"A≤ₘB\"},{\"t\":\"text\",\"v\":\"，能推出什么？只知道 \"},{\"t\":\"code\",\"v\":\"B≤ₘA\"},{\"t\":\"text\",\"v\":\" 时又能推出什么？\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"固定系统只有 K 个完整状态且确定运行、没有外部输入；若运行超过 K 次状态访问仍未停止，重复完整状态为何能证继续循环？这为何不推翻停机定理？\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"不同；前者是 \"},{\"t\":\"code\",\"v\":\"∃x，P(x) 停机\"},{\"t\":\"text\",\"v\":\"，而后者指定了一个 x，不能随意换量词或输入。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"它会一直模拟而不结束，所以不能作总停机判定器。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"前者推出 B 不可判定，否则可组合判定 A。仅后者不能推出 B 不可判定，一个很简单的可判定问题也可能归约到不可判定问题。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"K+1 次非停机状态访问必重复。确定性且无新外部输入保证之后后继完全相同，将重复同一段；但图灵机模型没有预先固定的完整状态总数上界，因为纸带内容可无界变化。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-14\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"MIT Theory of Computation 讲义\",\"href\":\"https://ocw.mit.edu/courses/18-404j-theory-of-computation-fall-2020/pages/lecture-notes/\"},{\"t\":\"text\",\"v\":\" — Sipser 第 6、8、9 讲，图灵模型、论题、不可判定与可计算归约。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"MIT Lecture 8：Undecidability\",\"href\":\"https://ocw.mit.edu/courses/18-404j-theory-of-computation-fall-2020/resources/mit18_404f20_lec8-1/\"},{\"t\":\"text\",\"v\":\" — 对角论证的公开讲义；本页完成标记的归约场景独立表述。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Mathematics for Computer Science\",\"href\":\"https://courses.csail.mit.edu/6.042/spring18/mcs.pdf\"},{\"t\":\"text\",\"v\":\" — 2018 版第 8 章含停机问题，用作离散数学与计算理论之间的桥梁。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Review of Proof-Writing\",\"href\":\"https://vertex.degree/appendix/proof-writing.html\"},{\"t\":\"text\",\"v\":\" — 本专题采用其澄清量词与算法终止的教学思路；停机问题不是该书的系统主题。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：自动机与形式语言\",\"href\":\"../12-automata-languages/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"下一节：复杂度与归约\",\"href\":\"../14-complexity-reductions/\"},{\"t\":\"text\",\"v\":\" →\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"从一个不可能的万能检查器开始\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"图灵机是模型，不是某台机器\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"可判定与可识别\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"HALT 能识别，却不能总判定\"},{\"id\":\"h-7\",\"level\":3,\"text\":\"归约：把已知难题变成目标问题\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"小例题\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例一：超时记录不是反例证明\"},{\"id\":\"h-10\",\"level\":3,\"text\":\"例二：把停机转成「是否触发完成标记」\"},{\"id\":\"h-11\",\"level\":2,\"text\":\"和工程、AI 的衔接\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-13\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-14\",\"level\":2,\"text\":\"资料索引\"}]},\"cs-theory/14-complexity-reductions\":{\"blocks\":[{\"t\":\"quote\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"link\",\"v\":\"计算机理论\",\"href\":\"../\"},{\"t\":\"text\",\"v\":\" › 复杂度与归约\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"有算法不代表规模变大时仍可承受；复杂度类别比较的是一族输入上的资源上界，而不是某台机器的一次耗时。\"}]},{\"t\":\"callout\",\"kind\":\"note\",\"blocks\":[{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"本仓库和站点的内容由 AI 生成，资料与资源链接来源于网络，仅供学习参考；如有错误或侵权，请提 Issue 告知。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"本关定位\",\"id\":\"h-1\"},{\"t\":\"table\",\"header\":[[{\"t\":\"text\",\"v\":\"项\"}],[{\"t\":\"text\",\"v\":\"内容\"}]],\"rows\":[[[{\"t\":\"text\",\"v\":\"所属专题\"}],[{\"t\":\"text\",\"v\":\"计算机理论 · 第 14 关；基础主线的并行选修\"}]],[[{\"t\":\"text\",\"v\":\"前置要求\"}],[{\"t\":\"text\",\"v\":\"03–05、08、11、13；已有大 O 概念。\"}]],[[{\"t\":\"text\",\"v\":\"本关边界\"}],[{\"t\":\"text\",\"v\":\"不展开 Cook–Levin 全证明、近似与参数化复杂度、量子复杂度。\"}]]]},{\"t\":\"h\",\"level\":2,\"text\":\"从「容易检查」和「容易找到」开始\",\"id\":\"h-2\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"给一组互不冲突的测试模块，逐对检查很容易；要求在任意冲突图中找到至少 k 个互不冲突的模块，就可能需要复杂搜索。这里的落差不是「不会写代码」，而是需要精确定义输入规模、答案类型和可验证证书。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"知识要点\",\"id\":\"h-3\"},{\"t\":\"h\",\"level\":3,\"text\":\"先固定判定问题与输入编码\",\"id\":\"h-4\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"P、NP 通常讨论答案为是或否的语言。优化问题「最大独立集有多大」对应判定版本「是否存在大小至少为 k 的独立集」；不要直接把两类定义混写。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"输入规模 N 是\"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"编码位数\"}]},{\"t\":\"text\",\"v\":\"，不是某个数的数值。例如二进制正整数 W 的长度为 \"},{\"t\":\"code\",\"v\":\"⌊log₂ W⌋+1\"},{\"t\":\"text\",\"v\":\"；一个 O(W) 时间算法可能对 W 的位长度是指数级，因此只按 W 多项式运行常被称为伪多项式，不能据此直接归入 P。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"已有 \"},{\"t\":\"link\",\"v\":\"DSA\",\"href\":\"../../cs-basics/06-data-structures-algorithms/\"},{\"t\":\"text\",\"v\":\" 讲大 O 和具体操作计数；本关不重讲排序表，而讨论「是否存在某类算法」及问题间转换。多项式时间也不等于实际一定快，巨大次数和常数仍可能不可用。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"P、NP 与证书\",\"id\":\"h-5\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"P\"}]},{\"t\":\"text\",\"v\":\"：存在确定算法，对每个输入都在输入长度的多项式时间内正确判定。\"}]},{\"inlines\":[{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"NP\"}]},{\"t\":\"text\",\"v\":\"：肯定实例有一个长度不超过输入长度某个多项式的证书，且存在确定的多项式时间验证器；否定实例不能有会被该验证器误接受的证书。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"NP 也等价于非确定图灵机多项式时间可判定的语言类，但它不是「Non-Polynomial」的缩写。P 包含于 NP，因为能直接快速判定，就可以忽略证书。NP 的定义并不要求「否」答案也有同样类型的短证书。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"例如大小至少 k 的独立集，证书可列出 k 个不同顶点；检查范围、去重及每对之间没有边即可，证书长度和验证时间都是图编码长度的多项式。证书不是「我相信能找到」的一句话。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"多项式归约与 NP 完全\",\"id\":\"h-6\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"多项式时间多对一归约 \"},{\"t\":\"code\",\"v\":\"A≤ₚB\"},{\"t\":\"text\",\"v\":\" 要求存在确定多项式时间映射 f，对每个实例 x 有 \"},{\"t\":\"code\",\"v\":\"x∈A ↔ f(x)∈B\"},{\"t\":\"text\",\"v\":\"。若 B 在 P 中，则 A 也在 P 中；复合的多项式仍是多项式。\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"B 是 \"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"NP-hard（NP 难）\"}]},{\"t\":\"text\",\"v\":\"：NP 中每个问题都能多项式归约到 B。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"B 是 \"},{\"t\":\"strong\",\"c\":[{\"t\":\"text\",\"v\":\"NP-complete（NP 完全）\"}]},{\"t\":\"text\",\"v\":\"：B 同时 NP-hard 且属于 NP。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"要证明新的 B 是 NP 完全，通常先证明 B 属于 NP，再从一个已知 NP 完全的 A 归约到 B，最后证明变换多项式且是/否答案双向等价。只做 \"},{\"t\":\"code\",\"v\":\"B≤ₚA\"},{\"t\":\"text\",\"v\":\"，说明 B 可以借 A 求解，不足以证明 B 已经同样难。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"引用 Cook–Levin 定理：SAT（命题公式是否存在满足赋值）是 NP 完全的；3-SAT、一般图的独立集、顶点覆盖、哈密顿圈判定也是标准 NP 完全问题。本关不提供这些既知起点的全部困难性证明；后面的归约演示从已知独立集开始。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"未解决不等于已经证明很慢\",\"id\":\"h-7\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"截至核对日期 2026-11-06，P 是否等于 NP 仍是开放问题。如果任意一个 NP 完全问题在 P 中，则 P=NP；若证明其中一个不在 P，就得到 P≠NP。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"NP 完全不是不可判定：标准有限编码下，NP 问题可用有限穷举判定，只是穷举可能极慢。也没有已知结论说所有 NP 完全问题的每一种实例都难，或已证明每种精确算法都必须指数时间。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"小例题\",\"id\":\"h-8\"},{\"t\":\"h\",\"level\":3,\"text\":\"例一：独立集与顶点覆盖互补\",\"id\":\"h-9\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"独立集 S 中任意两点没有边；顶点覆盖 C 要让每条边至少有一个端点落在 C。对同一简单图 G，有 \"},{\"t\":\"code\",\"v\":\"S 是独立集 ↔ V\\\\S 是顶点覆盖\"},{\"t\":\"text\",\"v\":\"：\"}]},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"若 S 内没有边，任何边至少有一端不在 S，故补集覆盖全部边。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"若补集覆盖全部边，就不存在两端都在 S 的边，故 S 独立。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"因此把独立集实例 \"},{\"t\":\"code\",\"v\":\"(G,k)\"},{\"t\":\"text\",\"v\":\"，其中 \"},{\"t\":\"code\",\"v\":\"0≤k≤n\"},{\"t\":\"text\",\"v\":\"，变成顶点覆盖实例 \"},{\"t\":\"code\",\"v\":\"(G,n−k)\"},{\"t\":\"text\",\"v\":\"，便有「至少 k 个独立点」当且仅当「至多 n−k 个覆盖点」。无需取图的补图，保持 G 不变；只换参数即可，多项式时间完成。这演示正确的困难性传递方向，不是从两道题外表相似就断言等价。\"}]},{\"t\":\"h\",\"level\":3,\"text\":\"例二：一个具体证书\",\"id\":\"h-10\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"冲突图 \"},{\"t\":\"code\",\"v\":\"V={a,b,c,d,e,f}\"},{\"t\":\"text\",\"v\":\"，边为 \"},{\"t\":\"code\",\"v\":\"ab, bc, cd, de, ef, fa, ad\"},{\"t\":\"text\",\"v\":\"。取 \"},{\"t\":\"code\",\"v\":\"S={a,c,e}\"},{\"t\":\"text\",\"v\":\"，其中三对点都没有边，所以是大小 3 的独立集。其补集 \"},{\"t\":\"code\",\"v\":\"{b,d,f}\"},{\"t\":\"text\",\"v\":\" 覆盖全部 7 条边，可逐条核验。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"这是一个实例的肯定证书，不证明所有同规模图都有 3 点独立集，也不证明搜索算法对所有图都快速。对于二分图的最大匹配、DAG 的拓扑排序、非负权最短路，前面已经给出多项式算法；「图问题」不是一个统一的难度标签。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"和 Java、微服务、AI 的衔接\",\"id\":\"h-11\"},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"业务的分配、排程、依赖优化可能包含困难的组合核心。实际可以限制输入结构、使用近似、启发式、分支定界、求解器并设置预算；但应该说明返回的是可行解、最优解还是尚未证明的候选。AI 很快给出一个方案，不等于证明全局最优，也不会自动改变该一般问题的最坏情况分类。\"}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"NP 难问题也可能在树、二分图或小参数条件下变容易；模型发生变化要重新论证，不能把一般图分类盲目移植过去。\"}]},{\"t\":\"h\",\"level\":2,\"text\":\"闯关任务\",\"id\":\"h-12\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能用编码长度而不是数值大小解释多项式时间。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能写清一个肯定证书及其验证步骤。\"}]},{\"inlines\":[{\"t\":\"text\",\"v\":\"☐ 能区分 NP 难与 NP 完全，检查归约方向和双向等价。\"}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"通关自测\",\"id\":\"h-13\"},{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"一个问题已有确定 O(N³) 判定算法，属于 P 吗？也属于 NP 吗？能断言所有输入都实际处理得很快吗？\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"已知 A 为 NP 完全，且 \"},{\"t\":\"code\",\"v\":\"A≤ₚB\"},{\"t\":\"text\",\"v\":\"。还需要证明 B 的什么性质，才能称 B 为 NP 完全？\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"在例二中独立集参数 k=3，对应顶点覆盖参数是多少？把 k 改为 4，如何只借一个顶点覆盖判定器来问原问题？\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"算法对二进制输入整数 W 执行 W 次循环，每次工作为常数；为什么不能直接说「线性，所以属于 P」？\"}],\"n\":4}]},{\"t\":\"fold\",\"blocks\":[{\"t\":\"ol\",\"items\":[{\"inlines\":[{\"t\":\"text\",\"v\":\"按 N 是输入编码长度的前提，它在 P，也在 NP。多项式分类不承诺具体常数、输入规模和工程耗时。\"}],\"n\":1},{\"inlines\":[{\"t\":\"text\",\"v\":\"已得 NP-hard，还要证明 B 属于 NP，即有多项式长度证书和多项式时间验证器；若 B 的编码或范围不标准，也要先定义清楚。\"}],\"n\":2},{\"inlines\":[{\"t\":\"text\",\"v\":\"参数为 3；k 为 4 时，问同一图是否有至多 \"},{\"t\":\"code\",\"v\":\"6−4=2\"},{\"t\":\"text\",\"v\":\" 个点的顶点覆盖，其答案等价于是否存在至少 4 个点的独立集。\"}],\"n\":3},{\"inlines\":[{\"t\":\"text\",\"v\":\"长度 N 的二进制整数可达接近 \"},{\"t\":\"code\",\"v\":\"2^N\"},{\"t\":\"text\",\"v\":\" 的数量级；W 次循环对 N 可能指数增长。数值线性不等于编码长度多项式。\"}],\"n\":4}]}]},{\"t\":\"h\",\"level\":2,\"text\":\"资料索引\",\"id\":\"h-14\"},{\"t\":\"ul\",\"items\":[{\"inlines\":[{\"t\":\"link\",\"v\":\"MIT Theory of Computation 讲义\",\"href\":\"https://ocw.mit.edu/courses/18-404j-theory-of-computation-fall-2020/pages/lecture-notes/\"},{\"t\":\"text\",\"v\":\" — Sipser 第 12、14–16 讲：时间复杂度、P/NP、归约、NP 完全和 Cook–Levin；本页证书数据独立设计。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"MIT Lecture 14：P and NP, SAT, Poly-time Reducibility\",\"href\":\"https://ocw.mit.edu/courses/18-404j-theory-of-computation-fall-2020/resources/mit18_404f20_lec14-1/\"},{\"t\":\"text\",\"v\":\" — 多项式证书与归约的正式定义。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"UC Davis：How to Prove a Problem Is NP-Complete\",\"href\":\"https://www.cs.ucdavis.edu/~bai/ECS122A/Notes/NPC3.pdf\"},{\"t\":\"text\",\"v\":\" — 无向哈密顿圈的 NP 完全分类，明确区别有向与无向版本。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Clay Mathematics Institute：P vs NP\",\"href\":\"https://www.claymath.org/millennium/p-vs-np/\"},{\"t\":\"text\",\"v\":\" — P vs NP 开放问题的权威介绍与状态入口。\"}]},{\"inlines\":[{\"t\":\"link\",\"v\":\"Start Doing Graph Theory：Cliques and Independent Sets\",\"href\":\"https://vertex.degree/hard/cliques.html\"},{\"t\":\"text\",\"v\":\" — 图论中的独立集、团与优化视角；不把该书当成复杂度类别定义的替代来源。\"}]}]},{\"t\":\"p\",\"inlines\":[{\"t\":\"text\",\"v\":\"← \"},{\"t\":\"link\",\"v\":\"上一节：可计算性与停机问题\",\"href\":\"../13-computability/\"},{\"t\":\"text\",\"v\":\" · \"},{\"t\":\"link\",\"v\":\"返回 计算机理论\",\"href\":\"../\"}]}],\"toc\":[{\"id\":\"h-1\",\"level\":2,\"text\":\"本关定位\"},{\"id\":\"h-2\",\"level\":2,\"text\":\"从「容易检查」和「容易找到」开始\"},{\"id\":\"h-3\",\"level\":2,\"text\":\"知识要点\"},{\"id\":\"h-4\",\"level\":3,\"text\":\"先固定判定问题与输入编码\"},{\"id\":\"h-5\",\"level\":3,\"text\":\"P、NP 与证书\"},{\"id\":\"h-6\",\"level\":3,\"text\":\"多项式归约与 NP 完全\"},{\"id\":\"h-7\",\"level\":3,\"text\":\"未解决不等于已经证明很慢\"},{\"id\":\"h-8\",\"level\":2,\"text\":\"小例题\"},{\"id\":\"h-9\",\"level\":3,\"text\":\"例一：独立集与顶点覆盖互补\"},{\"id\":\"h-10\",\"level\":3,\"text\":\"例二：一个具体证书\"},{\"id\":\"h-11\",\"level\":2,\"text\":\"和 Java、微服务、AI 的衔接\"},{\"id\":\"h-12\",\"level\":2,\"text\":\"闯关任务\"},{\"id\":\"h-13\",\"level\":2,\"text\":\"通关自测\"},{\"id\":\"h-14\",\"level\":2,\"text\":\"资料索引\"}]}}}");
